ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
UI_DIR = os.path.join(ROOT, "ui")

# ---- Зрение: фото клиента (🖼 URL в тексте) → image-блок для модели --------------
_IMG_RX = re.compile(r"🖼\s*(https?://\S+)")
_IMG_CACHE = collections.OrderedDict()   # url -> content-блок, с потолком (см. ниже)
_IMG_LOCK = threading.Lock()
_IMG_MAX_BYTES = 4_000_000
_IMG_PER_MSG = 4                 # не больше N картинок из одного сообщения
# ⚠ НЕУДАЧУ ЗАГРУЗКИ ПОМНИМ КОРОТКО, НО СЧИТАЕМ. Раньше сорвавшееся скачивание (таймаут, 5xx у
# media.jivosite) писалось в _IMG_CACHE как None НАВСЕГДА, и повторной попытки не было никогда за
# жизнь процесса: клиент присылал фото, а модель до конца диалога видела голый URL.
# Теперь в _IMG_CACHE лежат только УСПЕШНЫЕ блоки, а неудача — отдельно, с TTL и счётчиком.
# СЧЁТЧИК ОБЯЗАТЕЛЕН: по корпусу 64.3% ходов после фото наступают ПОЗЖЕ 120 с (медиана паузы
# 379 с), и без него мёртвый URL платил бы таймаут заново почти на каждом ходе.
_IMG_FAIL = collections.OrderedDict()   # url -> (когда сорвалось, сколько раз подряд)
_IMG_FAIL_TTL = 120
_IMG_FAIL_MAX = 3                # столько неудач подряд — и URL считаем мёртвым
try:
    from PIL import Image as _PILImage  # для удешевления: ужать большие фото перед отправкой
    import io as _io
except Exception:
    _PILImage = None


def _downscale(raw):
    """Ужимает фото по длинной стороне до config.vision_max_px (деф. 768) — меньше пикселей,
    меньше input-токенов. Маленькие (как миниатюры Avito) не трогает. Фолбэк — исходные байты."""
    if _PILImage is None:
        return raw, None
    cap = int(claude_api.config().get("vision_max_px", 768))
    try:
        im = _PILImage.open(_io.BytesIO(raw))
        if max(im.size) <= cap:
            return raw, None                 # уже мелкое — не пересжимаем
        im = im.convert("RGB")
        im.thumbnail((cap, cap))
        buf = _io.BytesIO()
        im.save(buf, "JPEG", quality=82)
        return buf.getvalue(), "image/jpeg"
    except Exception:
        return raw, None


#: ⚠ ПОТОЛОК КЭША КАРТИНОК (аудит 22.08, шаг 3). Машина бота — 2 ядра и 1.9 ГБ,
#: свободно около 1.4 ГБ, а кэш держал успешные блоки НАВСЕГДА и без счёта.
#: PIL на боевой машине не установлен, поэтому `_downscale` возвращает исходные
#: байты: одна запись — до 3.8 МБ сырыми, до 5.1 МБ в base64. Двести восемьдесят
#: фотографий, и памяти нет: процесс убивает OOM, канал умирает молча.
#: До 22.08 путь был почти мёртв (LeadChat вложений не передавал), сегодня утром
#: включён — счётчик пошёл именно сейчас.
#: Бюджет выбран от машины, а не от красивого числа: 64 МБ это 4.5% её памяти
#: и полтора десятка неужатых фото — кэшу как «ускорителю повтора» этого хватает.
_IMG_CACHE_MAX_ITEMS = 120
_IMG_CACHE_MAX_BYTES = 64 * 1024 * 1024
_IMG_FAIL_MAX_ITEMS = 512


def _img_block_size(block):
    """Сколько памяти занимает блок картинки — по длине base64, а не по объекту."""
    try:
        return len(((block or {}).get("source") or {}).get("data") or "")
    except AttributeError:
        return 0


def _img_cache_get(url):
    """Достать блок и освежить его в очереди вытеснения (иначе это не LRU)."""
    block = _IMG_CACHE.get(url)
    if block is not None:
        _IMG_CACHE.move_to_end(url)
    return block


def _img_cache_put(url, block):
    """Положить блок и вытеснить самое старое, пока не влезем в оба потолка."""
    if block is None:
        return
    _IMG_CACHE[url] = block
    _IMG_CACHE.move_to_end(url)
    занято = sum(_img_block_size(b) for b in _IMG_CACHE.values())
    while _IMG_CACHE and (len(_IMG_CACHE) > _IMG_CACHE_MAX_ITEMS
                          or занято > _IMG_CACHE_MAX_BYTES):
        _, ушедший = _IMG_CACHE.popitem(last=False)
        занято -= _img_block_size(ушедший)


def _img_fail_put(url, когда=None, счёт=None):
    """Отметить неудачу. Журнал тоже с потолком: адресов бесконечно много."""
    прежний = _IMG_FAIL.get(url)
    _IMG_FAIL[url] = (когда if когда is not None else time.time(),
                      счёт if счёт is not None else ((прежний[1] if прежний else 0) + 1))
    _IMG_FAIL.move_to_end(url)
    while len(_IMG_FAIL) > _IMG_FAIL_MAX_ITEMS:
        _IMG_FAIL.popitem(last=False)


#: ⚠ ЗРЕНИЕ БОТА — ЭТО ИСХОДЯЩИЙ ЗАПРОС С БОЕВОЙ МАШИНЫ (аудит 22.08).
#: Раньше скачивался ЛЮБОЙ адрес, найденный в тексте по шаблону «🖼 http…».
#: Рядом на этой машине живут панель (127.0.0.1:8788), приёмник Jivo
#: (127.0.0.1:8011), PostgreSQL и мост в СПб (10.10.0.2:8790), а у облака есть
#: служебный 169.254.169.254. Хуже того, тело ответа уходит В МОДЕЛЬ: байты, не
#: похожие на картинку, всё равно помечаются image/jpeg и кодируются в base64.
#: То есть внутренняя страница до 4 МБ выгружалась бы наружу и кэшировалась
#: навсегда.
#:
#: Список собран по корпусу, а не придуман: из 7324 картинок 7282 с
#: *.img.avito.st и 42 с *.jivo.ru. Отдельно отказываем адресам, которые
#: резолвятся в частную или служебную сеть, — это закрывает и подмену DNS у
#: разрешённого хоста.
_IMG_HOSTS = ("img.avito.st", "avito.st", "avito.ru", "jivo.ru", "jivosite.com")


def _image_media_type(raw):
    """Тип картинки по первым байтам. Не картинка — пусто, и мы её НЕ отправляем.

    Раньше неизвестные байты помечались «image/jpeg» и всё равно уезжали в
    модель. Значит любая страница, пришедшая вместо картинки (ошибка прокси,
    редирект на портал, внутренний ответ), выгружалась наружу в base64.
    Anthropic принимает ровно четыре формата — всё остальное бессмысленно
    отправлять даже когда оно безобидно.
    """
    if not raw:
        return ""
    if raw[:2] == b"\xff\xd8":
        return "image/jpeg"
    if raw[:4] == b"\x89PNG":
        return "image/png"
    if raw[:6] in (b"GIF87a", b"GIF89a"):
        return "image/gif"
    if raw[:4] == b"RIFF" and raw[8:12] == b"WEBP":
        return "image/webp"
    return ""


def _img_url_ok(url, resolve=None):
    """Можно ли ходить по этому адресу за картинкой."""
    import ipaddress
    import socket
    from urllib.parse import urlsplit

    try:
        u = urlsplit((url or "").strip())
    except ValueError:
        return False
    if u.scheme not in ("http", "https"):
        return False
    if u.username or u.password:          # «https://кто-то@разрешённый/…» — обход глазом
        return False
    if u.port not in (None, 80, 443):
        return False
    host = (u.hostname or "").lower().rstrip(".")
    if not host:
        return False
    if not any(host == s or host.endswith("." + s) for s in _IMG_HOSTS):
        return False
    try:
        адреса = resolve(host) if resolve else [
            i[4][0] for i in socket.getaddrinfo(host, None)
        ]
    except Exception:                     # noqa: BLE001 — не разрешилось, значит не идём
        return False
    if not адреса:
        return False
    for a in адреса:
        try:
            ip = ipaddress.ip_address(a)
        except ValueError:
            return False
        if (ip.is_private or ip.is_loopback or ip.is_link_local
                or ip.is_reserved or ip.is_multicast or ip.is_unspecified):
            return False
    return True


# ⚠ СКАЧИВАНИЕ СНИМКА ИДЁТ ВНУТРИ БЮДЖЕТА ОТВЕТА, И ТАЙМАУТ ОБЯЗАН БЫТЬ МЕНЬШЕ ЕГО.
# Здесь стояло 15 секунд при бюджете хода 9 (`leadchat.DEFAULT_TIMEOUT_S`): один медленный
# снимок съедал ход целиком — LeadChat переставал ждать раньше, чем мы успевали дойти до
# модели, и диалог уходил человеку с причиной «таймаут». Причём ход при этом ещё и
# оплачивался: нить дорабатывала в фоне. Берём треть бюджета и оставляем модели остальное.
_ТАЙМАУТ_СНИМКА_С = float(os.environ.get("LEADBOT_IMAGE_TIMEOUT_S") or 3.0)


def _fetch_image_block(url):
    """Скачивает картинку и возвращает Anthropic image-блок (base64). Кэшируется по URL."""
    with _IMG_LOCK:
        готовое = _img_cache_get(url)
        if готовое is not None:
            return готовое
        _f = _IMG_FAIL.get(url)
        if _f and (_f[1] >= _IMG_FAIL_MAX or time.time() - _f[0] < _IMG_FAIL_TTL):
            return None                      # недавно сорвалось либо сорвалось _IMG_FAIL_MAX раз
    if not _img_url_ok(url):
        print("[ЗРЕНИЕ] адрес не из списка разрешённых, не иду: %s" % (url or "")[:80],
              flush=True)
        with _IMG_LOCK:
            _img_fail_put(url, счёт=_IMG_FAIL_MAX)          # больше не пробовать
        return None
    block = None
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=_ТАЙМАУТ_СНИМКА_С) as r:
            raw = r.read(_IMG_MAX_BYTES + 1)
        media = _image_media_type(raw)
        if raw and media and len(raw) <= _IMG_MAX_BYTES:
            raw, new_media = _downscale(raw)     # ужать большие фото → дешевле
            if new_media:
                media = new_media
            block = {"type": "image", "source": {"type": "base64",
                     "media_type": media, "data": base64.b64encode(raw).decode()}}
    except Exception:
        block = None
    with _IMG_LOCK:
        if block is not None:
            _img_cache_put(url, block)       # помним, пока влезает в потолок
        else:                                # неудачу — на _IMG_FAIL_TTL и не больше _IMG_FAIL_MAX раз
            _img_fail_put(url)
    return block


def _content_with_images(text):
    """Если в тексте есть 🖼 URL — возвращает список блоков [картинки..., текст];
    иначе — исходную строку. Управляется config.vision (по умолчанию вкл)."""
    if not claude_api.config().get("vision", True):
        return text
    urls = _IMG_RX.findall(text or "")
    if not urls:
        return text
    blocks = []
    for u in urls[:_IMG_PER_MSG]:
        b = _fetch_image_block(u)
        if b:
            blocks.append(b)
    if not blocks:
        return text                              # не скачалось — оставляем текст-заглушку
    # ⚠ ЗДЕСЬ СТОЯЛО «оцени по изображению» — И ЭТО БЫЛ ПРЯМОЙ ПРИКАЗ ПОСТАВИТЬ ДИАГНОЗ.
    # Сообщение без текста — это только снимок, и заглушка ехала в модель речью клиента.
    # Отсюда «почистить компьютер от пыли надо» первой же фразой на фото системного блока
    # (снимок владельца 27.08): бот честно исполнил то, о чём его попросил наш собственный код.
    # Снимок нужен, чтобы ПОНЯТЬ задачу и сделать шаг, а не чтобы описать увиденное вслух.
    clean = _IMG_RX.sub("", text).strip() or (
        "(клиент прислал фото и ничего не написал. Посмотри на снимок и веди разговор дальше: "
        "вслух его НЕ описывай и причину не называй)")
    blocks.append({"type": "text", "text": clean})
    return blocks

# ---- Хранилище диалогов (в памяти) --------------------------------------
_LOCK = threading.Lock()
#: ⚠ ПОТОЛОК И ЗАМОК НА ДИАЛОГ (аудит 22.08, шаг 3, находка Д-019).
#: Словарь только пополнялся — чистила его одна ручка `/api/reset`. И работа с
#: ним шла так: под общим замком прочитать состояние, ОТПУСТИТЬ замок, звать
#: модель секунды, снова взять замок и записать СВОЙ снимок целиком. Два хода по
#: одному диалогу внахлёст затирали друг друга: воспроизведено 10 раз из 10 —
#: телефон, который клиент назвал, исчезал из заявки молча.
#: Сегодня `run_turn` зовёт ровно один путь — `/api/message` (тест-чат панели);
#: живой канал и мост LeadChat ходят стейтлесс. Но путь остаётся заряженным.
_DIALOGS = collections.OrderedDict()   # dialog_id -> dict, с потолком
_DIALOGS_MAX = 200
_DIALOG_LOCKS = collections.OrderedDict()   # dialog_id -> Lock, живёт вместе с диалогом


def _dialog_lock(dialog_id):
    """Замок ЭТОГО диалога: одновременные ходы по одному чату идут по очереди,
    разные чаты друг друга не ждут."""
    with _LOCK:
        lk = _DIALOG_LOCKS.get(dialog_id)
        if lk is None:
            lk = _DIALOG_LOCKS[dialog_id] = threading.Lock()
        _DIALOG_LOCKS.move_to_end(dialog_id)
        while len(_DIALOG_LOCKS) > _DIALOGS_MAX + 5:
            _DIALOG_LOCKS.popitem(last=False)
        return lk
_SEQ = 0

