# ⚠ ОТКРЫТЫЙ ВОПРОС О ВРЕМЕНИ — ЗАПРЕТ ЗАКАЗЧИКА ОТ 02.08, И ОДНИМ ПРОМПТОМ ОН НЕ ДЕРЖИТСЯ.
# Замер 13.08, три прогона по десять сценариев: после чистки пулов воронки запрещённый вопрос
# никуда не делся — его пишет САМА МОДЕЛЬ, по 2-3 раза на десять диалогов, и от прогона к
# прогону состав меняется. Правило в промпте стоит прямым текстом с примерами; модель его
# всё равно нарушает, потому что «двинуть разговор к времени» — сильный позыв, а окна у неё
# в этот момент может не быть.
#
# Воронка тут не помогает вовсе: `_ensure_question` выходит сразу, если в реплике уже есть
# «?», — а он есть, это же и есть тот самый вопрос. Значит чинить надо ПОСЛЕ модели.
_OPEN_TIMEQ_RX = re.compile(
    r"[^.!?]*\b(?:"
    # «когда вам БЫЛО БЫ удобно» — между «вам» и «удобно» помещается вставка, и без неё
    # шаблон промахивался мимо фразы, вписанной прямо в `_ensure_close` (поймано 13.08)
    r"когда\s+вам\s+(?:\w+\s+){0,2}удобн\w*"
    r"|во\s?сколько\s+вам\s+(?:\w+\s+){0,2}удобн\w*"
    r"|в\s+как(?:ое|ой)\s+время\s+вам\s+удобн\w*"
    r"|когда\s+(?:смож\w+|може\w+)\s+принять"
    r"|когда\s+вам\s+(?:помощь\s+)?нужн\w*"
    r"|когда\s+вас\s+ждать"
    r"|когда\s+могу\s+к\s+вам\s+(?:приехать|подъехать)"
    r"|когда\s+удобн\w+\s+(?:принять|подъехать|приехать)"
    r"|когда\s+удобно"
    r")[^.!?]*\?",
    re.IGNORECASE)

#: Конкретное окно в ТОЙ ЖЕ фразе делает вопрос законным: «Могу через час-полтора, удобно
#: вам будет?» — это предложение, а не открытый вопрос. Без этой проверки сторож переписывал
#: бы собственные правильные формулировки воронки.
_WINDOW_IN_PHRASE_RX = re.compile(
    r"\d{1,2}[:.]\d{2}|\bк\s+\d{1,2}\b|час[аоу]?[-\s]*полтора|\bчерез\s+\d|\bчерез\s+час",
    re.IGNORECASE)


def _offer_instead_of_open_time(reply, slot_offer="", has_addr=False, first=False,
                                offered_before=False):
    """Меняет запрещённый «когда вам удобно?» на предложение окна.

    В-025 (владелец, 21.08): открытая форма РАЗРЕШЕНА ВТОРОЙ — живые так делают в 49+
    победных диалогов. offered_before=True (в прошлых репликах бота время уже звучало) —
    открытый вопрос уходит как есть; первое предложение времени по-прежнему только окном.

    ЕСТЬ ОКНО — предлагаем его: «Могу сегодня к 10:00-10:30, удобно вам будет?». Это ровно
    то, чего требует правило: окно предлагает бот, а не выпрашивает у клиента.

    ОКНА НЕТ (город неизвестен, 18.6% потока) — выдумывать час нельзя, но и открытый вопрос
    оставлять нельзя. Тогда просим адрес, обещая время сразу за ним: клиент получает ответ
    по существу, а не встречный вопрос.

    ⚠ ПОЧЕМУ ПРАВИМ ТОЛЬКО ПРЕДЛОЖЕНИЕ С ВОПРОСОМ, А НЕ ВСЮ РЕПЛИКУ. В реплике перед этим
    вопросом обычно стоит содержательная часть («от 500р, точнее скажу когда посмотрю») —
    её терять нельзя, она и есть ответ клиенту. Режем ровно одно предложение.
    """
    if offered_before and not first:
        return reply                      # В-025: вторая форма разрешена
    r = reply or ""
    m = _OPEN_TIMEQ_RX.search(r)
    if not m:
        return reply
    if _WINDOW_IN_PHRASE_RX.search(m.group(0)):
        return reply                      # окно названо здесь же — это предложение, не запрет
    # адрес уже дан или это первый ответ (логистика под запретом 05.08) — открытый вопрос
    # просто убираем: пустая замена схлопнет предложение, реплика останется без него
    замена = ("Могу %s, удобно вам будет?" % slot_offer if slot_offer
              else "" if (has_addr or first)
              else "Назовите адрес — сразу сориентирую по времени.")
    r = (r[:m.start()] + " " + замена + r[m.end():])
    r = re.sub(r"[ \t]{2,}", " ", r)
    r = re.sub(r"\s+([,.!?])", r"\1", r)
    return r.strip()


#: Клиент СПРАШИВАЕТ про время. Узко и прямо: «когда», «во сколько», «пораньше».
_CLIENT_ASKS_TIME_RX = re.compile(
    r"(когда\s+(?:смож\w+|може\w+|приед\w+|подъед\w+|буде\w+|вы\s+буде\w+)"
    r"|во\s?сколько(?!\s*(?:обойд|встан|выйд|сто[ии]|будет\s+сто|руб|₽))"
    r"|в\s+какое\s+время"
    r"|пораньше"
    r"|как\s+скоро"
    r"|успе\w+\s+(?:ли\s+)?сегодня)",
    re.IGNORECASE)

#: Время в НАШЕМ ответе названо: час, день или длительность. Слово «время» само по себе —
#: не ответ («уточню по времени» ответом не является, за что этот сторож и взялся).
_TIME_ANSWERED_RX = re.compile(
    r"(\d{1,2}[:.]\d{2}|\bк\s+\d{1,2}\b|\bпосле\s+\d{1,2}\b"
    r"|час[аоу]?[-\s]*полтора|\bчерез\s+час|\bчерез\s+\d"
    # ⚠ СПУТНИКОВАЯ ФОРМУЛИРОВКА (аудит регламента 18.08): окно спутника —
    # «два, два с половиной часа», в ней нет ни «полтора», ни цифры после
    # «через». Гард считал, что время не названо, и клеил своё окно ВТОРЫМ
    # пузырём: клиент получал одно и то же предложение дважды подряд.
    r"|дв[ае][,\s]+дв[ае]\s+с\s+половин|дв[ае]\s+с\s+половиной\s+час|"
    r"\bдва\s+час|\bтри\s+час"
    r"|\bсегодня\b|\bзавтра\b|\bпослезавтра\b"
    r"|понедельник|вторник|сред[уы]|четверг|пятниц[уы]|суббот[уы]|воскресень)",
    re.IGNORECASE)


#: ОТГОВОРКА ВМЕСТО ВРЕМЕНИ. Формально вежливо, по сути — отказ отвечать: клиент просил
#: окно, а получил обещание написать позже, о котором не просил. Такое предложение целиком
#: заменяется на окно, потому что рядом с окном оно ему противоречит.
_TIME_STALL_RX = re.compile(
    r"[^.!?]*\b(?:"
    r"уточню\s+(?:по\s+)?врем\w*"
    r"|вернусь\s+к\s+вам"
    r"|дам\s+знать\s+(?:по\s+)?врем\w*"
    r"|сориентирую\s+(?:вас\s+)?поздн\w*"
    r"|напишу\s+(?:вам\s+)?поздн\w*"
    r"|уточню\s+и\s+(?:напишу|вернусь|сообщу)"
    r")[^.!?]*[.!?]?",
    re.IGNORECASE)


def _answer_time_question(reply, last_client, slot_offer="", needs_approval=False):
    """Клиент спросил «когда?» — в ответе обязано быть время. Иначе дописываем.

    ⚠ ЭТО САМАЯ ДОРОГАЯ ТОЧКА ВОРОНКИ. По отчёту операторов (46 690 диалогов) конкретное
    окно времени называется лишь в 17-21% записей — из четырёх точек потери лида это худшая.
    Замер 13.08 показал её живьём: клиент спрашивал «а во сколько сегодня могли бы?», получал
    вопрос про адрес, переспрашивал «а пораньше никак?» — и уходил: «ну ладно, надо подумать».

    Отговорка считается НЕответом наравне с молчанием. «Уточню по времени и вернусь к вам» —
    это обещание перезвонить, которого клиент не просил, вместо окна, которое он просил.

    ⚠ СВЕРКА С ФИЛИАЛОМ — ОТДЕЛЬНЫЙ СЛУЧАЙ, И ТУТ ДОПИСЫВАТЬ НЕЛЬЗЯ. Там ответ приходит не
    от нас: пообещать «сориентирую сразу» значит соврать. Молчание честнее.
    """
    r = (reply or "").strip()
    if not r or needs_approval:
        return reply
    if not _CLIENT_ASKS_TIME_RX.search(last_client or ""):
        return reply
    if _TIME_ANSWERED_RX.search(r):
        return reply
    if slot_offer:
        хвост = "Могу %s, удобно вам будет?" % slot_offer
    elif _ADDR_RX.search(last_client or "") or _похоже_на_адрес(last_client or ""):
        # ⚠ КЛИЕНТ ДАЛ АДРЕС В ЭТОЙ ЖЕ РЕПЛИКЕ (аудит 30.08): «Стиралка течёт. Адрес:
        # … Когда будете?» получал «Назовите адрес» — переспрос собранного, класс
        # «два пути считают одно поле по-разному».
        хвост = "Сегодня подъеду — по адресу сориентируюсь и напишу точнее."
    elif _ADDRQ_RX.search(r):
        # ⚠ АДРЕС УЖЕ СПРОШЕН В ЭТОЙ ЖЕ РЕПЛИКЕ — второй раз не просим. Поймано на себе:
        # сторож дописывал «Назовите адрес…» к реплике «Адрес подскажите (улица, дом,
        # квартира, подъезд) и номер для связи», и клиент видел одну просьбу дважды подряд.
        # Ответ на вопрос о времени при этом всё равно нужен — оставляем только его.
        хвост = "Сегодня подъеду — по адресу сразу сориентирую по времени."
    else:
        хвост = "Сегодня подъеду. Назовите адрес — сразу сориентирую по времени."
    # ⚠ ОТГОВОРКУ ЗАМЕНЯЕМ, А НЕ ДОПОЛНЯЕМ. «Уточню по времени и вернусь к вам» рядом с
    # «Могу через час-полтора, удобно?» читается как спор с самим собой: сперва обещал
    # выяснить и написать позже, тут же назвал окно. Клиенту непонятно, что из этого правда.
    m = _TIME_STALL_RX.search(r)
    if m:
        r = (r[:m.start()] + " " + хвост + r[m.end():])
        r = re.sub(r"[ \t]{2,}", " ", r)
        return re.sub(r"\s+([,.!?])", r"\1", r).strip()
    # отдельным пузырём: у живых операторов вопрос-хвост так и уходит (36.6% ходов)
    return r.rstrip() + "\n" + хвост


def _soften_booking(reply, речь_клиента=""):
    """Убирает утверждение о состоявшейся записи, оставляя предложенное время.

    ⚠ ХВОСТ «ПОДТВЕРЖУ БЛИЖЕ К ДЕЛУ» ДОПИСЫВАЕТСЯ ТОЛЬКО ПО ПРОСЬБЕ КЛИЕНТА (снимок
    владельца 26.08). Дословно: «Подтвержу ближе к делу — это условно прозвон перед
    выездом, клиент это не просил, значит так писать не нужно». Это тот же запрет, что
    уже стоит на «наберу перед выездом» (`_CALLBEFORE_RX`): обещание звонка, которого
    никто не просил, вместо шага к записи. Раньше хвост дописывался ВСЕГДА, стоило
    смягчить запись, и на живом диалоге вышло «буду у вас 18:00. Подтвержу ближе к делу».
    """
    r = (reply or "")
    if not r.strip():
        return r
    before = r
    for rx, sub in _BOOKED_SOFTEN:
        r = rx.sub(sub, r)
    _смягчено = r != before
    r = re.sub(r"\s{2,}", " ", r).replace(" ,", ",").strip()
    # после удаления слова остаётся «Хорошо, И номер…» — запятая перед новым предложением
    #
    # ⚠ ТОЛЬКО ЕСЛИ СМЯГЧЕНИЕ ДЕЙСТВИТЕЛЬНО ПРОИЗОШЛО (находка по живым диалогам 23.08).
    # Строка стояла ЗА воротами и выполнялась для КАЖДОЙ реплики, а вызов из
    # _postprocess_reply безусловный. Заплатка на шве работала глобальным редактором
    # пунктуации и рвала любое перечисление с именем собственным:
    #
    #   «ВК, Мах и Авито поставлю»      → «ВК. Мах и Авито поставлю»   ← ушло клиенту
    #   «Понял, Атлант. Давайте подъеду» → «Понял. Атлант. Давайте подъеду»
    #   «Здравствуйте, Игорь»            → «Здравствуйте. Игорь»
    #
    # Замер по корпусу проекта (4178 сохранённых реплик): 38 содержат «, Заглавная», и
    # 37 из них — БЕЗ слова «запис», то есть правило срабатывало вхолостую и только портило.
    # Показательна была и непоследовательность: класс [А-ЯЁ] только кириллический, поэтому
    # «Стиралку беру, Bosch тем более» оставалось целым, а «Понял, Атлант» ломалось.
    if _смягчено:
        r = re.sub(r",\s+(?=[А-ЯЁ])", ". ", r)
    _просил_звонок = bool(речь_клиента and _CALL_OK_BASE_RX.search(речь_клиента)
                          and not _CALL_NEG_RX.search(речь_клиента))
    # ⚠ «ЗАПИШУ ВАС НА …» ТЕПЕРЬ ЛЕГАЛЬНА и не смягчается (аудит 30.08) — но хвост
    # «подтвержу» по просьбе клиента обязан вставать и на ней: клиент попросил звонок
    # перед выездом, форма записи это не отменяет.
    _есть_запись = bool(re.search(r"запишу\s+вас|буду\s+у\s+вас", r, re.IGNORECASE))
    if ((r != before or _есть_запись) and _просил_звонок
            and _CONFIRM_TAIL.lower() not in r.lower()
            and _SLOT_IN_REPLY_RX.search(r)):
        r = r.rstrip()
        if not r.endswith(("?", ".", "!")):
            r += "."
        _hc = int(hashlib.sha256(r.encode("utf-8")).hexdigest(), 16)
        r = r + " " + _pick_unused(_ХВОСТ_ПОДТВЕРЖУ, "", _hc)
    return r


#: ⚠ ОБЕЩАННЫЙ ЧАС В ПРОШЛОМ (находка по живым диалогам 23.08). В 21:15 по клиенту наружу
#: ушло «буду у вас сегодня к 15:30-16:00, до встречи» — час, который прошёл шесть часов
#: назад, и он же лёг в карточку CRM (`_visit_from_reply`), то есть мастер не выедет ни
#: сегодня, ни завтра.
#:
#: Генератор окна здесь НИ ПРИ ЧЁМ: он проверен на всех 24 часах суток и окна в прошлом не
#: даёт ни разу, от часового пояса сервера не зависит. Час пришёл от модели — в промпте
#: намертво вписаны дневные примеры («могу сегодня к 15:00-15:30, удобно?»), а в пуле RAG
#: 319 примеров из 4140 несут конкретный час и показываются модели в любое время суток.
#:
#: Беда в том, что НИКТО не сверял названный час с часами клиента: `tm_hour` встречается в
#: коде восемь раз и все восемь — внутри самого генератора окна. Сквозной проход на четырёх
#: часах (21:15, 23:50, 00:10, 05:00) прошёл без единой правки во всех четырёх.
# ⚠ ПЕРВАЯ РЕДАКЦИЯ ВИДЕЛА ТОЛЬКО ПРЕДЛОГ «К» И ЛОМАЛА ГРАММАТИКУ (правка 24.08, вечер).
# Пробник по десяти живым формам: ловилась одна. «Могу сегодня в 15:00» — самая частая
# форма — проходила мимо, а «сегодня ближе к 15 часам» превращалось в «завтра к 10:00-10:30
# ближе часам»: вырезался только час, а предлог и хвост оставались сиротами.
#
# Теперь берётся ВЕСЬ оборот целиком — от слова «сегодня» до конца часа — и заменяется
# одной строкой. Сироте взяться неоткуда: мы не вырезаем кусок из фразы, мы подменяем
# связный оборот связным оборотом.
_ОБЕЩАННЫЙ_ЧАС_RX = re.compile(
    r"\bсегодня\b"                                      # оборот всегда начинается отсюда
    r"(?P<связка>[^.!?\n]{0,30}?)"                       # «могу», «буду у вас», «подъеду»
    # ⚠ ГОЛОЕ ЧИСЛО ЧАСОМ НЕ СЧИТАЕТСЯ. «Сегодня 8 позиций посмотрю» — это количество, а не
    # время, и подстановка окна превращала фразу в «завтра к 10:00-10:30 позиций посмотрю».
    # Час обязан быть назван ОДНИМ ИЗ ТРЁХ способов: предлогом, минутами или словом «часов».
    r"(?:"
    r"(?:к|в|во|около|после|примерно\s+к|ближе\s+к)\s*(?P<ч1>\d{1,2})(?:[:.](?P<м1>\d{2}))?(?!\d)"
    r"|(?P<ч2>\d{1,2})[:.](?P<м2>\d{2})(?!\d)"
    r"|(?P<ч3>\d{1,2})\s*(?:часов|часам|часа|ч)\b"
    r")"
    r"(?:\s*(?:часов|часам|часа|ч)\b)?"                 # «к 15 часам»
    r"(?:\s*[-–—/]\s*(?P<ч4>\d{1,2})(?:[:.](?P<м4>\d{2}))?(?!\d))?",   # конец окна
    re.IGNORECASE)
#: день назван ЯВНО и он не сегодняшний — такую фразу не трогаем вовсе
_ДЕНЬ_НЕ_СЕГОДНЯ_RX = re.compile(
    r"завтра|послезавтра|понедельник|вторник|сред[ауы]|четверг|пятниц|суббот|воскресень",
    re.IGNORECASE)
#: запас на пограничный случай: «буду сегодня к 21:00», написанное в 20:58, переписывать
#: нельзя — мастер успевает. Правим только то, что прошло с заведомым запасом.
_ЗАПАС_МИН = 15


def _без_прошедшего_часа(reply, city="", slot=""):
    """Час, который уже прошёл, обещать нельзя. Возвращает (реплика, была_ли_правка).

    Сверяем с часами КЛИЕНТА (`territory.city_localtime`), а не сервера: 35.7% заявок
    приходят ночью, и ночь — его. У диапазона «к 15:30-16:00» берём КОНЕЦ: если и он
    позади, случай однозначен и спорить не с чем.
    """
    r = reply or ""
    if not r.strip() or "сегодня" not in r.lower():
        return r, False
    lt = territory.city_localtime(city)
    сейчас = lt.tm_hour * 60 + lt.tm_min
    куски = re.split(r"(?<=[.!?])\s+|\n", r)
    итог, менялось = [], False
    for к in куски:
        if not к.strip() or "сегодня" not in к.lower() or _ДЕНЬ_НЕ_СЕГОДНЯ_RX.search(к):
            итог.append(к)
            continue
        m = _ОБЕЩАННЫЙ_ЧАС_RX.search(к)
        if not m:
            итог.append(к)
            continue
        нач_ч = int(m.group("ч1") or m.group("ч2") or m.group("ч3"))
        нач_м = int(m.group("м1") or m.group("м2") or 0)
        кон_ч = int(m.group("ч4")) if m.group("ч4") else нач_ч
        кон_м = int(m.group("м4") or 0) if m.group("ч4") else нач_м
        # ⚠ У ДИАПАЗОНА СМОТРИМ КОНЕЦ: если и он позади, спорить не с чем. И проверяем
        # ОБА числа на осмысленность — «сегодня в 130» это не час, а мусор.
        if not (0 <= нач_ч <= 23 and 0 <= кон_ч <= 23 and нач_м <= 59 and кон_м <= 59):
            итог.append(к)
            continue
        if кон_ч * 60 + кон_м >= сейчас - _ЗАПАС_МИН:
            итог.append(к)
            continue
        # Час позади. Есть честное окно — подставляем его; нет (город неизвестен или нужна
        # сверка с филиалом) — снимаем обещание совсем: молчать о времени честнее, чем врать.
        # ⚠ ПОДМЕНЯЕМ ВЕСЬ ОБОРОТ ЦЕЛИКОМ, вместе с «сегодня» и связкой из group(1): вырезание
        # одного часа оставляло сирот («ближе часам»), и это заметнее исходной ошибки.
        связка = (m.group("связка") or "").strip()
        замена = slot or "время уточню и сразу напишу вам"
        if связка:
            замена = "%s %s" % (связка, замена)
        новый = к[:m.start()] + замена + к[m.end():]
        новый = re.sub(r"\s{2,}", " ", новый).replace(" ,", ",").replace(" .", ".").strip()
        итог.append(новый or замена)
        менялось = True
    return ("\n".join(x for x in итог if x.strip()) if менялось else r), менялось


def _не_второе_окно(reply, prior_bot="", last_client=""):
    """Второе время визита не называется, пока живо первое (хвост №4 аудита 30.08).

    Боевой случай: «договорились, буду через час-полтора» и через 40 секунд «буду у
    вас 14:00-14:30» — обещание из пула и расчётный слот считались разными путями
    (класс «два пути считают одно поле по-разному»), и клиент получил два времени.
    Новое цифровое окно законно, только если клиент сам заговорил о времени
    (перенос, «а можно к N?»); иначе предложение с окном снимается.
    """
    r = (reply or "")
    if not r.strip() or not _CLOCK_RX.search(r):
        return reply
    if not (_SOFT_WINDOW_RX.search(prior_bot or "") or _CLOCK_RX.search(prior_bot or "")):
        return reply
    if _TIME_RX.search(last_client or ""):
        return reply                      # клиент сам о времени — новое окно уместно
    куски = [к for к in re.split(r"(?<=[.!?])\s+|\n", r) if к.strip()]
    оставили = [к for к in куски if not _CLOCK_RX.search(к)]
    if len(оставили) == len(куски):
        return reply
    if not оставили:
        # реплика целиком из нового окна — заменяем подтверждением прежнего
        logbook.event("leadbot.second_slot_replaced")
        return "Буду у вас, как договорились"
    вышло = "\n".join(оставили).strip()
    logbook.event("leadbot.second_slot_removed")
    return вышло or reply


def _ensure_slot_clock(reply, prior_bot="", slot_offer=""):
    r = (reply or "").strip()
    if not r or "?" in r:
        return reply
    if not _q_clock(slot_offer):
        # окна нет — молчим. Раньше здесь уходил открытый «во сколько вам удобно?», причём
        # в самый дорогой момент: к реплике согласия. Лучше без хвоста, чем с запрещённым.
        return reply
    if _SOFT_WINDOW_RX.search(r):        # окно уже названо словами — второй вопрос лишний
        return reply
    # окно цифрами уже называлось раньше и клиент его принял — «Записал вас, ожидайте» законен
    if _CLOCK_RX.search(prior_bot or ""):
        return reply
    # ⚠ РАНЬШЕ ТРЕБОВАЛОСЬ ЕЩЁ И РАЗМЫТОЕ ВРЕМЯ В САМОЙ РЕПЛИКЕ, и «Записал вас, до встречи» /
    # «Хорошо, записал. Ожидайте» проходили насквозь — запись без окна вообще. Ранний выход по
    # prior_bot выше уже защищает от повтора, когда окно цифрами звучало раньше.
    if _BOOKED_REPLY_RX.search(r) and not _CLOCK_RX.search(r):
        h = int(hashlib.sha256(r.encode("utf-8")).hexdigest(), 16)
        return r + "\n" + _pick_unused(_q_clock(slot_offer), prior_bot, h)
    return reply


def _ensure_close(reply, problem_known=True, direction="", slot_offer="", first=False,
                  has_addr=False, job=False):
    """Правило заказчика: удержание этапа 2 («выезд бесплатный, на месте обсудим») не должно
    оставлять ход открытым — если в реплике нет вопроса, дожимаем окном.
    Реплики, уже фиксирующие запись («запишу/записал»), не трогаем — там свой финал.

    ⚠ 13.08. ТРЕТИЙ ИСТОЧНИК ЗАПРЕЩЁННОГО ОТКРЫТОГО ВОПРОСА — И САМЫЙ НЕЗАМЕТНЫЙ. Пулы
    `_Q_TIME` и `_Q_CLOCK` видно поиском по спискам фраз, а здесь строка «Когда вам было бы
    удобно?» была вписана прямо в код одним `r +=`. Ротации у неё нет: клиент получал её
    дословно каждый раз. Мимо сторожа `_offer_instead_of_open_time` она тоже проходила —
    формулировка «когда ВАМ БЫЛО БЫ удобно» не совпадала ни с одним шаблоном (шаблон с тех
    пор расширен, но чинить надо в источнике, а не заплаткой на выходе).

    ⚠ 12.08: дожим шёл ВСЛЕПУЮ и ломал главное правило воронки. На «Выезд платный?» бот честно
    отвечал «по городу выезд бесплатный» — и тут же звал на приезд, хотя поломка НЕ НАЗВАНА.
    Гард логистики это не ловил: он отрабатывает раньше, а хвост приклеивался после него.
    Пока сути нет — дожимаем вопросом о сути, а не о времени."""
    r = (reply or "").strip()
    if r and _HOLD_RX.search(r) and "?" not in r and "запис" not in r.lower():
        if r[-1] not in ".!…":
            r += "."
        if problem_known and slot_offer and not first:
            r += " Могу %s, удобно вам будет?" % slot_offer
        elif problem_known and not first and not has_addr:
            # окна нет (город неизвестен, сверка или ранний ход) — выдумывать час нельзя, а
            # открытый вопрос запрещён. Тянем к адресу: от него и считается время.
            r += " Назовите адрес — сразу сориентирую по времени."
        elif problem_known:
            # первый ответ (логистика запрещена правилом 05.08) или адрес уже дан клиентом
            # («не переспрашивай уже данное») — дожим пропускаем, вопрос допишет воронка
            pass
        else:
            h = int(hashlib.sha256(r.encode("utf-8")).hexdigest(), 16)
            r += " " + _pick_unused(_q_pools(direction, job)[0], "", h)
    return r


# ---- ЖИВЫЕ ТАЙМИНГИ ОТПРАВКИ (бот = человек с телефоном, не мгновенная нейросеть) -----------
# По корпусу: клиенты досылают мысль 2-5 сообщениями (нужен буфер тишины), зазор между
# пузырями операторов ~6 сек, скорость набора с телефона ~3-5 символов/сек.
_UNFINISHED_RX = re.compile(r"[,;:\-]\s*$|\b(?:и|а|но|ещё|еще|также|плюс|потом|значит)\s*$", re.IGNORECASE)


# ── ДЕБАУНС СЕРИИ СООБЩЕНИЙ (для автоматического канала Jivo, задача #6) ────────────
# Клиент дописывает мысль частями: «здравствуйте» → «стиралка не отжимает» → «Bosch».
# Отвечать на каждое сообщение — это и три вызова модели вместо одного, и мгновенный маркер
# бота: живой мастер не отвечает на полфразы.
# ЗАМЕР ПО КОРПУСУ (6733 диалога, 30 552 сообщения клиента): серий подряд идущих сообщений
# 20 147, то есть **34.1% вызовов лишние**. Из одного сообщения 68.3% серий, из двух 20.3%,
# из трёх и больше 11.4%. При 868 диалогах/сут это до 31 800 ₽/мес, при 3000 — до 110 000 ₽/мес.
# ⚠ СЕГОДНЯ НЕ ПРИМЕНЯЕТСЯ: модель зовут вручную из Пульта, автоматического канала ещё нет.
# Функция написана заранее, чтобы канал #6 сразу работал правильно.
# ⚠ ПЕРЕСЧИТАНО 21.08 по правилам базы знаний №59 и №67 (ДИАЛОГ-И-ПАУЗЫ.md).
# Было: 12 с обычной реплике, 35 с незаконченной и РОВНО НОЛЬ реплике с «?».
# Ноль означает мгновенный ответ, а мгновенный ответ на вопрос выдаёт автомат
# надёжнее любой формулировки: живой мастер не успевает прочитать и ответить за
# секунду. И вопрос — не исключение по сути: «сколько стоит?» сплошь и рядом
# продолжается адресом и моделью техники следующим сообщением.
_DEBOUNCE_BASE_S = (20, 25)    # законченная реплика
_DEBOUNCE_MAX_S = (35, 45)     # незаконченная: обрыв на союзе, короткий обрывок
_DEBOUNCE_ASK_S = (15, 20)     # прямой вопрос — короче, но НЕ ноль


def debounce_wait(last_client, seconds_since_last=0.0):
    """Сколько ещё секунд ждать продолжения, прежде чем звать модель. 0 — отвечать можно.

    Ждём дольше, если реплика выглядит НЕЗАКОНЧЕННОЙ: обрыв на запятой или союзе, либо очень
    короткий фрагмент без знака конца («здравствуйте», «а», «Bosch»). Признак тот же, что в
    _timing_plan, — не заводим второй, чтобы они не разъехались.
    ⚠ Вопрос НЕ ждём: на прямой вопрос («сколько стоит?») пауза читается как игнор.
    """
    t = (last_client or "").strip()
    if not t:
        return 0.0
    unfinished = bool(_UNFINISHED_RX.search(t)) or (len(t) < 18 and not re.search(r"[.?!)]$", t))
    if unfinished:
        окно = _DEBOUNCE_MAX_S
    elif t.endswith("?"):
        окно = _DEBOUNCE_ASK_S
    else:
        окно = _DEBOUNCE_BASE_S
    # ровная пауза у всех ответов — тоже примета автомата, поэтому разброс внутри
    # окна; детерминированный по тексту, чтобы повторный проход дал то же число
    import hashlib
    зерно = int(hashlib.sha256(t.encode("utf-8")).hexdigest(), 16)
    need = окно[0] + зерно % (окно[1] - окно[0] + 1)
    return max(0.0, need - max(0.0, float(seconds_since_last or 0)))


def _timing_plan(last_client, reply, turn_index=0):
    """План человеческой отправки ответа: сколько подождать (клиент может дописывать),
    сколько «печатать» каждый пузырь (по длине), зазоры между пузырями.
    Рандом детерминированный (хэш содержимого) — живой разброс, но воспроизводимо."""
    lc = (last_client or "").strip()
    rp = (reply or "").strip()
    if not rp:
        return None
    h = int(hashlib.sha256((lc + "|" + rp).encode("utf-8")).hexdigest(), 16)

    def rnd(a, b, salt):
        return a + ((h >> salt) & 0xFFFF) % (b - a + 1)

    # 1) «прочитал»: длинное сообщение клиента читается дольше
    read_s = min(15, 2 + len(lc) // 40) + rnd(1, 4, 3)
    # 2) «реакция»: первый ответ дольше (мастер «был занят»), дальше короче
    react_s = rnd(6, 18, 7) + (rnd(8, 20, 11) if turn_index == 0 else 0)
    # 3) буфер «клиент дописывает»: обрыв на запятой/союзе или короткий фрагмент без знака конца
    unfinished = bool(_UNFINISHED_RX.search(lc)) or (len(lc) < 18 and not re.search(r"[.?!)]$", lc))
    wait_more_s = rnd(15, 30, 13) if unfinished else 0
    # 4) набор по пузырям: ~3-5 симв/сек, зазор между пузырями 3-9 сек (как у операторов)
    bubbles = []
    for i, b in enumerate([x.strip() for x in rp.split("\n") if x.strip()]):
        typing_s = min(28, max(2, len(b) // rnd(3, 5, 17 + 2 * i)))
        gap_s = rnd(3, 9, 23 + 2 * i) if i else 0
        bubbles.append({"text": b, "typing_s": typing_s, "gap_s": gap_s})
    wait_s = read_s + react_s + wait_more_s
    total_s = wait_s + sum(x["typing_s"] + x["gap_s"] for x in bubbles)
    return {"wait_before_s": wait_s, "maybe_client_typing": unfinished,
            "bubbles": bubbles, "total_s": total_s,
            "note": ("клиент, похоже, дописывает — подождать" if unfinished else "")}


# ⚠ Группа обращения по имени («Здравствуйте, Игорь») ОБЯЗАНА быть регистрозависимой: под общим
# re.IGNORECASE она совпадала с любым словом в нижнем регистре после запятой и съедала первое
# слово реплики («Здравствуйте, подъеду сегодня» → «сегодня»; «Здравствуйте, нет» → пусто).
# (?-i:…) отключает игнор регистра точечно, только для заглавной буквы имени.
# ⚠ ОБРАЩЕНИЕ ПО ИМЕНИ СРЕЗАЕМ ОСТОРОЖНО. Голое (?-i:[А-ЯЁ][а-яё]+) съедало ЛЮБОЕ слово с
# заглавной после запятой, а не только имя: «Здравствуйте, По какому адресу подъехать?» →
# «какому адресу подъехать?» (8 случаев на корпусе). Исключаем слова, которыми начинается
# обычное предложение, — имя среди них не встречается.
_NOT_A_NAME = (r"По|Как|Что|Куда|Когда|Где|Какой|Как(?:ая|ое|ие)|Скажите|Подскажите|Уточните|"
               r"Нужно|Можно|Давайте|Хорошо|Записал|Запишу|Беру|Могу|Буду|Сейчас|Спасибо|Да|Нет|"
               r"Отлично|Понял|Принял|Адрес|Номер|Марку|Модель|Вы|Ваш|Это|Тогда|Значит")
_GREET_RX = re.compile(
    r"^\s*(?:" + _GREET_CORE + r")(?:\s*,\s*(?-i:(?!(?:" + _NOT_A_NAME + r")\b)[А-ЯЁ][а-яё]+))?"
    r"[\s!.,\-—]*", re.IGNORECASE)


def _strip_greeting(text):
    """Срезает приветствие в начале — если бот уже здоровался в этой переписке."""
    t = _GREET_RX.sub("", text or "", count=1).strip()
    return t or (text or "")


# ── ЗАЩИТА ОТ СЖИГАНИЯ ЛИМИТА API (красная команда 04.08.2026) ──────────────────
# Модель угрозы: у недовольного сотрудника (или тролля) есть только чат — но каждое
# его сообщение уходит в тело запроса как есть. Стена в 200 КБ — это ~50 тыс. токенов
# и ~$0.05 за ОДИН ход; слать такое можно бесконечно. Замер по 13 886 реальных реплик
# клиентов: медиана 33 символа, p99.9 = 741, АБСОЛЮТНЫЙ максимум = 990. Ставим потолки
# с двукратным запасом — живого клиента они не заденут, атаку срезают на 99%.
_MSG_CAP = 2000            # символов на одну реплику
_HIST_MSGS = 40            # сколько последних реплик уходит модели
_HIST_CHARS = 15000        # общий потолок текста диалога
_RUN_CHAR_RX = re.compile(r"(.)\1{40,}")      # «ааааа…» и эмодзи-заливка


def _cap_input(norm):
    """Обрезает вход до разумных размеров: длинные реплики, длинную историю, заливку."""
    out = []
    for m in norm:
        t = _RUN_CHAR_RX.sub(lambda mo: mo.group(1) * 40, m["text"])
        if len(t) > _MSG_CAP:
            t = t[:_MSG_CAP] + " […]"
        out.append({"role": m["role"], "text": t, "свой": bool(m.get("свой"))})
    if len(out) > _HIST_MSGS:
        # первая реплика клиента — это сама заявка, её сохраняем всегда
        first_client = next((x for x in out if x["role"] == "client"), None)
        tail = out[-_HIST_MSGS:]
        out = ([first_client] + tail) if first_client and first_client not in tail else tail
    total = sum(len(x["text"]) for x in out)
    while total > _HIST_CHARS and len(out) > 2:
        drop = out.pop(1 if len(out) > 2 else 0)     # выкидываем самое старое из середины
        total -= len(drop["text"])
    return out


#: Причины, при которых заявку создаёт ЧЕЛОВЕК, а не бот. Список именно такой и не длиннее:
#: чёрный список и мультиаккаунт — это отказ работать вовсе, согласование — решение филиала.
#: Всё остальное («визит назначен», «Спасибо», жалоба, просьба перезвонить) — обычные концовки
#: живого диалога, и терять на них собранную заявку не за что.
_БЕЗ_ЗАЯВКИ = {"blocklist", "multi_account", "soglasovanie", "soglas"}


def _человек_писал(messages):
    """Писал ли в диалоге ЖИВОЙ оператор (не бот). Заявку в таком диалоге заводит он.

    ⚠ ЗАЩИТЫ ОТ ДУБЛЯ С РУЧНОЙ ЗАЯВКОЙ У БОТА НЕТ ВОВСЕ: `prefilter.active_zayavka` —
    заглушка, всегда None, а собственный ключ бота знает только его же заявки. Владелец
    заводит карточку руками ровно тогда, когда диалог забрал человек, — значит признак
    «человек здесь уже говорил» и есть самая честная защита из доступных сегодня.
    Отличать бота от человека мы научились 26.08 (поле `by` от панели, `свой` в разборе).
    """
    return any(m.get("role") != "client" and not m.get("свой") and (m.get("text") or "").strip()
               for m in messages or [])


def _доклад_о_заявке(res, norm, known):
    """Досчитать заявку на ЛЮБОМ выходе хода и отдать её на создание. Ошибка тут хода не роняет."""
    try:
        if not isinstance(res, dict) or res.get("error"):
            return
        if res.get("lead_ready") and res.get("lead"):
            return                       # модельный путь уже всё посчитал и создал
        причина = str(res.get("notify_reason") or "")
        фл = res.get("flag") if isinstance(res.get("flag"), dict) else {}
        if причина in _БЕЗ_ЗАЯВКИ or str(фл.get("kind") or "") in _БЕЗ_ЗАЯВКИ \
                or str(фл.get("sub") or "") in _БЕЗ_ЗАЯВКИ:
            return
        if _человек_писал(norm):
            return
        клиент = [m for m in norm if m.get("role") == "client"]
        if not клиент:
            return
        речь = " \n".join(m.get("text") or "" for m in клиент)
        телефон = bool(prefilter.phones_in(речь)) or bool(_glue_phone([m.get("text") or "" for m in клиент]))
        адрес = bool(_адрес_в_переписке(norm))
        # проверку «есть телефон и адрес» не дублируем: она первой строкой в _lead_ready,
        # и вторая копия здесь ничего не ловит — диверсия это показала
        посл_бот = next((m.get("text") or "" for m in reversed(norm)
                         if m.get("role") != "client" and (m.get("text") or "").strip()), "")
        город = (known or {}).get("city") or ""
        # ⚠ РЕПЛИКА ЭТОГО ХОДА ПУСТА — И ЭТО НЕ ПОВОД ТЕРЯТЬ ЗАЯВКУ. Окно клиент услышал
        # РАНЬШЕ, из `посл_бот`; именно это и проверяет липкое согласование.
        лид = _lead_ready(посл_бот or " ", речь, телефон, prior_bot=посл_бот, has_addr=адрес,
                          last_client=(клиент[-1].get("text") or ""), посл_бот=посл_бот,
                          city=город, окно_принято=_окно_принято(norm))
        if not лид:
            return
        if territory.is_closed(город):
            return
        res["lead"] = лид
        res["lead_ready"] = True
        _kr = {k: (known or {}).get(k)
               for k in ("visitor", "city", "title", "direction", "persona",
                         "partner", "white", "origin", "review_url")}
        _maybe_autocreate(res, _kr, known, norm)
    except Exception as e:              # noqa: BLE001 — заявка не имеет права уронить ход
        logbook.event("leadbot.lead_late_error", error=str(e)[:200])


def run_relay(messages, known=None):
    """Ход бота: эскалация выше всех гардов, затем обычный разбор, затем единый контракт.

    Обёртка появилась 12.08 из-за находки заказчика: смысл «отправлять ли текст» ехал на
    пустой строке, а «звать ли человека» — на двух флагах, которые в автоканале Avito
    значили разное (`handoff` отправку не блокировал вообще, а проверка на метку
    «оператору» в channel.py оказалась мёртвым кодом). Здесь смысл выражается явно:
    `reply_text` — что отправить, `notify_human` — звать ли человека, `escalation` —
    почему. Старые флаги вычисляются поверх, чтобы не ломать Пульт и LeadChat."""
    # ⚠ «СВОЙ» ОБЯЗАН ЕХАТЬ И ЗДЕСЬ. Этот список уходит в `_доклад_о_заявке`, а тот спрашивает
    # `_человек_писал` — «заводил ли карточку живой оператор». Без пометки КАЖДАЯ реплика бота
    # выглядит человеческой, признак всегда True, и заявка на ранних выходах не создаётся НИ РАЗУ:
    # правка, ради которой заведена единая точка, оказалась бы мёртвой в бою. Проверено прогоном
    # 27.08: те же три реплики без пометки дают True, с пометкой — False.
    norm0 = [{"role": ("client" if m.get("role") == "client" else "operator"),
              "text": (m.get("text") or ""),
              "свой": bool(m.get("свой"))}
             for m in (messages or []) if (m.get("text") or "").strip()]
    last_client0 = next((m["text"] for m in reversed(norm0) if m["role"] == "client"), "")
    if last_client0 and not prefilter.check_blocklist((known or {}).get("visitor")):
        esc = escalation.detect(
            last_client0,
            all_client_text=" \n".join(m["text"] for m in norm0 if m["role"] == "client"),
            bot_history=" \n".join(m["text"] for m in norm0 if m["role"] == "operator"),
            booked=bool(_BOOKED_BH_RX_SAFE(" ".join(m["text"] for m in norm0
                                                    if m["role"] == "operator"))),
            known=known)
        if esc:
            spoke = any(m["role"] == "operator" for m in norm0)
            txt = "" if esc["silent"] else esc["reply"]
            # ⚠ ЗАЯВКА СОБРАНА ИЛИ РАЗГОВОР ВЕДЁТ ЧЕЛОВЕК — ДАЛЬШЕ МОЛЧИМ (слово
            # владельца 26.08, дословно: «если понятно, что заявка создана, на
            # последующие сообщения можно не отвечать и ждать, когда диалог примет
            # оператор»).
            #
            # Роутер эскалации стоит ВЫШЕ заслона первичности и потому обходил его.
            # Эталон 26.08 поймал два таких хода на живой выборке: «сегодня всё в силе?»
            # (визит назначен) и «перенесём на завтра» (оператор сделал пять ходов) —
            # в обоих бот вклинился мостиком. Мостик задумывался, чтобы клиент не висел
            # в тишине, но здесь тишина и есть правильный ответ: и график, и историю
            # знает человек, а бот их не видит.
            #
            # ⚠ ЗАСЛОН БЕРЁМ ТОТ ЖЕ САМЫЙ (`_молчать_почему`), а не пишем второй. Два
            # разных ответа на вопрос «мой ли это диалог» разъехались бы при первой же
            # правке — сегодня я чинил ровно такие расхождения весь день.
            #
            # ⚠ ЧЕЛОВЕКА ЗОВЁМ ПО-ПРЕЖНЕМУ: молчание касается только текста клиенту,
            # `notify` ниже не трогаем, иначе диалог просто потеряется.
            _молчим = _молчать_почему(norm0, known) if txt else ""
            if _молчим:
                _log_escalation(esc["reason"], "роутер эскалации: %s" % _молчим, last_client0)
                txt = ""
            # ⚠ ВОПРОС ГРАФИКА ПОСЛЕ ЗАПИСИ — ТИШИНА (слово владельца 26.08, потерянное
            # правкой _молчать_почему 27.08). «Сегодня всё в силе?» и «перенесём на
            # завтра» бот по существу закрыть не может: график у человека. Мостик
            # «уточню и вернусь» — отговорка, а отговорка считается НЕответом. Молчим
            # ТОЛЬКО на статус/перенос при состоявшейся записи — прочие эскалации
            # (претензия, недовольство) мостик сохраняют; правка 27.08 про «сама
            # реплика решает» остаётся в силе для всего, что записью не заперто.
            if txt and esc["reason"] in ("status", "reschedule") \
                    and _BOOKED_BH_RX_SAFE(" ".join(m["text"] for m in norm0
                                                    if m["role"] == "operator")):
                _log_escalation(esc["reason"],
                                "роутер эскалации: график после записи знает человек",
                                last_client0)
                txt = ""
            if txt and _is_white(known):
                txt = _WHITE_ESC_REPLIES.get(esc["reason"], txt)
            if txt:
                # ⚠ приветствие клеим ПОСЛЕ стилевого слоя: _humanize опускает первую букву
                # реплики ради живости, и «Здравствуйте» превращалось в «здравствуйте»
                txt = _humanize(_no_dash(txt))
                if not spoke:
                    txt = "Здравствуйте\n" + txt
            _log_escalation(esc["reason"], "роутер эскалации", last_client0)
            # ⚠ в событие кладём и саму реплику клиента. Причина эскалации — это ярлык, а в
            # реплике может быть вторая половина смысла: «когда приедете, сможете ещё гардину
            # переделать?» — статус перебивает по приоритету, но гардина это деньги, и она
            # не должна раствориться, если очередь построят на событии, а не на чате.
            return _contract({
                "reply": txt,
                "flag": {"kind": "escalation", "sub": esc["reason"], "reason": esc["label"]},
                "model": "локальный роутер (эскалация: %s)" % esc["reason"],
                "state": {"category": "unknown"}, "missing": list(prompt.REQUIRED_FIELDS),
                "ready": False, "done": False, "usage": None},
                notify=True, reason=esc["reason"], note=last_client0)
    res = _contract(_run_relay_inner(messages, known=known))
    # ⚠⚠ ЕДИНАЯ ТОЧКА ЗАКРЫТИЯ ХОДА. Заявку умел создать ТОЛЬКО модельный путь: вызов
    # `_maybe_autocreate` стоит последней строкой `_run_relay_inner`, а роутеров, закрывающих
    # ход раньше, там семнадцать. Любой из них — «визит уже назначен», жалоба, «Спасибо»,
    # просьба перезвонить, эскалация — уносил собранную заявку с собой. Замер по локальной
    # выгрузке: из 427 ходов с передачей человеку заявка есть у 0.
    # Снимок владельца 27.08: телефон, адрес и согласованное время собраны, бот молчит по
    # правилу «визит уже назначен» — и владелец заводит заявку руками.
    _доклад_о_заявке(res, norm0, known)
    # ⚠ РАЗМЕТКА — ТОЛЬКО В РЕЖИМЕ ОБУЧЕНИЯ. В бою заметку читает смена, и служебное
    # «решил: claude-sonnet-5; длина 84 зн.» ей мешает: она ждёт там причину передачи.
    if _РЕЖИМ_ОБУЧЕНИЯ and isinstance(res, dict) and not res.get("error"):
        try:
            метка = _разметка_хода(res, norm0, known)
        except Exception as e:      # разметка не имеет права уронить ход
            метка = "🎓 Разметка бота — не собралась: %s" % e
        res["note"] = (str(res.get("note") or "").strip() + "\n" + метка).strip()
    return res


# «Белый» аккаунт (партнёр 723): негатив гасим подчёркнутой учтивостью — регламент 15.08
# требует успокоить и пообещать связь, любая сухость бьёт штрафом по рейтингу аккаунта.
# claim в словаре нет нарочно: претензия остаётся МОЛЧАЛИВОЙ передачей человеку.
_WHITE_ESC_REPLIES = {
    "discontent": "Прошу прощения за неудобства. В самое ближайшее время с вами свяжусь, "
                  "разберёмся и всё решим",
    "status": "Сейчас уточню по времени. В самое ближайшее время с вами свяжусь",
    "no_show": "Прошу прощения за ожидание. Сейчас уточню и в самое ближайшее "
               "время с вами свяжусь",
    "reschedule": "Конечно, перенесём. В самое ближайшее время вернусь "
                  "к вам с подтверждением",
    "prior_master": "Сейчас подниму историю вашего обращения. В самое ближайшее время с "
                    "вами свяжусь",
    # ⚠ БЕЗ СЛОВА «ЗАЯВКА» (аудит 30.08): cancel чаще всего срабатывает БЕЗ записи,
    # и «снимаю заявку» выдумывал заявку, которой не было — основной пул переписан
    # этой же правкой 26.08, белую ветку тогда не тронули.
    "cancel": "Понял вас, спасибо, что предупредили. Если что-то ещё понадобится — "
              "напишите, помогу",
}


def _BOOKED_BH_RX_SAFE(blob):
    try:
        return prefilter._BOOKED_BH_RX.search((blob or "").lower())
    except Exception:
        return None


def _log_escalation(reason, source, text):
    """Одна строка в журнал с устойчивым префиксом — по ней считается очередь эскалаций.

    ⚠ Реплику клиента в журнал НЕ пишем (аудит 15.08): journald читает любой, у кого
    есть ssh на машину, а клиенты диктуют в чат адреса и телефоны. Содержимое
    переписки живёт в панели; журналу достаточно факта, причины и длины — по длине
    видно, была ли реплика вообще.
    """
    try:
        print("[ЭСКАЛАЦИЯ] причина=%s источник=%s длина=%d"
              % (reason, source, len(text or "")), flush=True)
    except Exception:
        pass


# ── СОБЫТИЕ «ЛИД ГОТОВ» ─────────────────────────────────────────────────────
# Диалог, дошедший до предложенного окна и телефона, обязан попасть к человеку на
# подтверждение — но ОТДЕЛЬНЫМ событием, а не через очередь эскалаций. Иначе очередь
# недовольств и претензий утонет в успешных заявках и перестанет что-либо показывать.
# ⚠ Календаря у нас нет: бот предлагает время, подтверждает его человек. Поэтому событие
# несёт и предложенное окно — чтобы подтверждающий видел, что именно обещано клиенту.
_SLOT_IN_REPLY_RX = re.compile(r"\b\d{1,2}[:.]\d{2}(?:\s*[-–—]\s*\d{1,2}[:.]\d{2})?|"
                               r"\bк\s*\d{1,2}\b|в\s*течение\s*часа", re.IGNORECASE)


# ── ГОТОВНОСТЬ ЗАЯВКИ: ТРИ ВЕЩИ, А НЕ ОДНА ──────────────────────────────────────────
# ⚠ ПРАВИЛО ВЛАДЕЛЬЦА 26.08, дословно: «бот считает, если клиент дал номер, то заявка
# собрана — это не так. Заявка будет собрана на 100 %, когда мы знаем номер, адрес и
# есть договорённость по времени. Но если мы имеем телефон и адрес клиента, но нет
# договорённости по времени, мы такую заявку можем создать и поставить её на прозвон».
#
# ЧТО БЫЛО НЕ ТАК. Прежняя формула — «телефон есть И в реплике БОТА нашлись часы» —
# считала заявку собранной по тому, что предложил САМ БОТ. Клиент мог не ответить на
# окно вовсе или ответить «я подумаю», а карточка уже уезжала в CRM с датой визита:
# мастер выезжал на время, о котором не договаривались. Адрес в формуле не участвовал
# совсем — заявка уходила без места работы, и диспетчер узнавал об этом, открыв карточку.
#
# ТРИ СОСТОЯНИЯ:
#   None      — заявки нет: нет номера ЛИБО нет адреса. Продолжаем собирать.
#   "прозвон" — номер и адрес есть, времени не согласовали. Заявку СОЗДАЁМ, ставим
#               галочку «Прозвон» и время, когда набрать (сказанное клиентом или +4 часа).
#   "полная"  — номер, адрес и договорённость по времени. Заявка с датой визита.
_ПРОЗВОН_ЧЕРЕЗ_Ч = 4

#: Согласие на предложенное ботом окно. Короткие подтверждения, которыми живой клиент
#: отвечает на «могу сегодня к 17:00, удобно?». Работает ТОЛЬКО когда бот в прошлом ходе
#: действительно назвал окно: голое «да» без окна рядом — это ответ на другой вопрос.
_СОГЛАСИЕ_НА_ОКНО_RX = re.compile(
    r"\b(?:да|ага|угу|ок|окей|окей|хорошо|хорошо|отлично|подойд[её]т|подходит|подходить|"
    r"удобно|устраивает|устроит|договорились|согласен|согласна|дава(?:й|йте)|"
    r"жду|жд[её]м|ждем|буду\s+ждать|будем\s+ждать|приезжай\w*|подъезжай\w*|"
    r"приезжайте|годится|пойд[её]т|давайте\s+так|можно\s+так)\b", re.IGNORECASE)

#: Клиент ОТЛОЖИЛ время — договорённости нет, что бы ни стояло в диалоге раньше.
#: Этот вето сильнее всех подтверждений: «давайте в 15… хотя нет, я перезвоню» — прозвон.
_ВРЕМЯ_НЕ_РЕШЕНО_RX = re.compile(
    r"не\s+знаю|пока\s+не\s+(?:знаю|готов\w*|мог\w*|скаж\w*|определ\w*)|"
    r"уточн[юяии]\w*|надо\s+уточнить|позже\s+(?:скаж\w*|напиш\w*|отвеч\w*|определ\w*)|"
    r"определ\w*\s+(?:позже|потом|утром|завтра|вечером)|"
    r"перезвон\w*|позвон\w+\s+(?:мне|попозже|позже|вечером|завтра|потом)|"
    r"набер[иеё]т?[еь]?\b|наберите|свяжитесь|созвон\w*|"
    r"я\s+(?:напишу|отпишу\w*|перезвоню|позвоню|свяжусь|наберу)|"
    r"надо\s+подумать|подума\w+|как\s+освобожусь|когда\s+освобожусь|"
    r"не\s+могу\s+сказать|ещ[её]\s+не\s+решил\w*|не\s+определилс\w*",
    re.IGNORECASE)

#: Не единица измерения после числа — иначе «в 32 дюйма» и «за 5 лет» станут часом.
#: Свой список, а не `_NOT_TIME_UNIT`: тому нельзя пропускать «час», а нам нужно
#: («наберите в 7 часов» — это ровно наш случай).
#: ⚠ ГРАНИЦЫ У ЕДИНИЦ И АДРЕСНЫЕ СЛОВА (полный разбор 31.08). Две беды сразу.
#: Первая: «см» и «гр» без границы съедали живое — «В 6 СМОЖЕТЕ?» переставало быть часом.
#: Вторая: адресные слова в списке отсутствовали, и «Кленовая д.46 К2 кв 117» читалось
#: как назначенный час. Заявка помечалась «полной», час брался из реплики самого бота, а
#: галочка прозвона оставалась снятой — диспетчер получал карточку с выдуманным временем.
#: На корпусе таких адресных ложных срабатываний 37, плюс 22 года («в 2016») и 12 «числа».
_НЕ_ЧАС_ЕДИНИЦА = (r"(?!\s*(?:тыс|тысяч|руб|₽|%|кг|\bгр\b|\bсм\b|\bмм\b|метр\w*|\bм\b|штук|\bшт\b|"
                   r"градус|лет\b|год\w*|мес\w*|дней|дюйм|канал|минут|\bмин\b|"
                   r"числ|корп|\bк\d|\bстр\b|\bкв\b|подъезд|этаж))")

#: Клиент НАЗВАЛ ЧАС сам. Часовая форма самодостаточна: в диалоге о ремонте «после 18»
#: и «к 17:00» про время визита, а не про что-то ещё.
_ЧАС_ОТ_КЛИЕНТА_RX = re.compile(
    # ⚠ `(?!\d)` ПОСЛЕ ЧАСА ОБЯЗАТЕЛЕН (31.08): без него «в 2016 году покупали» отдавало
    # час «20» — движок брал первые две цифры года и считал, что клиент назвал время.
    r"\b(?:в|к|с|после|ближе\s+к)\s*(\d{1,2})(?:[:.](\d{2}))?(?!\d)" + _НЕ_ЧАС_ЕДИНИЦА +
    r"|\bс\s*\d{1,2}\s*до\s*\d{1,2}\b" + _НЕ_ЧАС_ЕДИНИЦА, re.IGNORECASE)

#: День или часть суток. ⚠ САМ ПО СЕБЕ ДОГОВОРЁННОСТЬЮ НЕ ЯВЛЯЕТСЯ: «сегодня сломалась
#: стиралка» — это про поломку, а не про визит. Нужен рядом разговор о приезде.
_ДЕНЬ_ОТ_КЛИЕНТА_RX = re.compile(
    r"\b(?:" + _ДЕНЬ_ГРУППА + r")\b|утром|с\s+утра|вечером|под\s+вечер|к\s+вечеру|"
    r"дн[её]м|после\s+обеда|в\s+обед|(?:перв|втор)\w*\s+половин\w*\s+дня", re.IGNORECASE)

#: Речь о приезде — тот контекст, в котором день превращается в договорённость.
_ПРИЕЗД_В_РЕЧИ_RX = re.compile(
    r"приезжай\w*|приех\w*|приед\w*|подъезжай\w*|подъех\w*|подъед\w*|"
    r"удобн\w*|дава(?:й|йте)|устро\w*|подойд\w*|подход\w*|жду|жд[её]м|ждем|"
    r"смож\w*|получится|запиш\w*|записать|ждать\s+вас|буду\s+дома|будем\s+дома",
    re.IGNORECASE)

#: Звонок ПЕРЕД визитом — не отмена договорённости, а её дополнение: «давайте завтра
#: к 11, только наберите, как будете подъезжать». Свой шаблон, а не `_CALLBEFORE_RX`:
#: тот написан под РЕПЛИКУ БОТА («я наберу перед выездом»), здесь же речь клиента.
_ЗВОНОК_ПЕРЕД_ВИЗИТОМ_RX = re.compile(
    r"перед\s+(?:выездом|приездом|выходом|тем\s+как)|до\s+(?:выезда|приезда)|"
    r"(?:как|когда)\s+(?:буд[еы]те\s+)?(?:подъезж|подъед|выезж|выед|приед|прие[дх])|"
    r"за\s+\d+\s*(?:[-–]\s*\d+\s*)?минут", re.IGNORECASE)

#: Просьба набрать — вокруг неё ищем, КОГДА набрать.
_КОГДА_НАБРАТЬ_RX = re.compile(
    r"перезвон\w*|позвон\w*|набер\w*|наберите|наб(?:рать|ери\w*)|свяжитесь|созвон\w*|"
    r"звонит[еь]", re.IGNORECASE)

#: Час из куска речи: «после 18», «в 6 вечера», «часов в 7», «в 19:30».
_ЧАС_В_ФРАЗЕ_RX = re.compile(
    r"(?:после|ближе\s+к|часов\s+в|часам\s+к|\bв\b|\bк\b|\bс\b)\s*(\d{1,2})"
    r"(?:[:.](\d{2}))?" + _НЕ_ЧАС_ЕДИНИЦА + r"\s*(?:час\w*\s*)?(вечера|утра|дня|ночи)?",
    re.IGNORECASE)

#: Части суток → час, когда набирать. Утро берём не в 8, а в приёмное время города.
_ЧАСТИ_СУТОК = ((r"поздн\w*\s+вечер", 20),
                (r"под\s+вечер|вечером|к\s+вечеру", 18),
                (r"после\s+обеда|в\s+обед|дн[её]м", 14),
                (r"с\s+утра|утром|к\s+утру", 0))     # 0 = «к открытию приёма»


def _час_из_фразы(фраза):
    """(час, минута) из речи о звонке. Ничего не нашли — None."""
    for m in _ЧАС_В_ФРАЗЕ_RX.finditer(фраза or ""):
        ч = int(m.group(1))
        мин = int(m.group(2) or 0)
        суффикс = (m.group(3) or "").lower()
        # «в 6 вечера» = 18:00; «в 2 дня» = 14:00. Утро и ночь оставляем как сказано.
        if суффикс.startswith(("вечер", "дня")) and ч <= 11:
            ч += 12
        if 0 <= ч <= 23 and 0 <= мин <= 59:
            return ч, мин
    for шаблон, ч in _ЧАСТИ_СУТОК:
        if re.search(шаблон, фраза or "", re.IGNORECASE):
            return ч, 0
    return None


def _окна_вокруг(текст, rx, радиус=60):
    """Куски речи вокруг совпадений — чтобы «наберите» и «после шести» читались вместе,
    в каком бы порядке клиент их ни написал."""
    t = текст or ""
    куски = []
    for m in rx.finditer(t):
        куски.append(t[max(0, m.start() - радиус):min(len(t), m.end() + радиус)])
    return " \n".join(куски)


def _в_приёмные_часы(lt, earliest, latest):
    """Двигаем момент в приёмное окно города: раньше открытия — к открытию,
    позже закрытия — на утро следующего дня. Звонок в три ночи — не сервис."""
    def _чм(hhmm, по_умолчанию):
        try:
            ч, м = [int(x) for x in str(hhmm).split(":")]
            return ч, м
        except (ValueError, AttributeError):
            return по_умолчанию
    ео, ем = _чм(earliest, (11, 0))
    ло, лм = _чм(latest, (21, 30))
    сейчас = lt.tm_hour * 60 + lt.tm_min
    if сейчас < ео * 60 + ем:
        return _сдвиг_времени(lt, день=0, час=ео, минута=ем)
    if сейчас > ло * 60 + лм:
        return _сдвиг_времени(lt, день=1, час=ео, минута=ем)
    return lt


def _сдвиг_времени(lt, день=0, час=None, минута=None, часов=0):
    """struct_time города со сдвигом. Часовых поясов не трогаем: считаем стенные часы
    того города, где живёт клиент, — тем же приёмом, что и `_visit_from_reply`."""
    base = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday,
                        lt.tm_hour if час is None else час,
                        lt.tm_min if минута is None else минута,
                        0, 0, 0, -1))
    return time.localtime(base + день * 86400 + часов * 3600)


def _время_прозвона(client_all, last_client, city):
    """Когда набрать клиента: (дата dd-mm-yyyy, время HH:MM, повод).

    Правило владельца: «спросить у клиента, когда его набрать, и поставить на прозвон на
    то время, когда клиент сказал, или поставить на прозвон +4 часа от текущего времени».
    Сказанное клиентом всегда сильнее умолчания — он назвал час, значит будет у телефона.
    """
    lt = territory.city_localtime(city)
    prof = territory.slot_profile(city)
    early, late = prof.get("earliest") or "11:00", prof.get("latest") or "21:30"
    речь = " \n".join(t for t in (client_all or "", last_client or "") if t)
    окно = _окна_вокруг(речь, _КОГДА_НАБРАТЬ_RX) or (last_client or "")
    час = _час_из_фразы(окно)
    дм = re.search(r"\b(" + _ДЕНЬ_ГРУППА + r")\b", окно, re.IGNORECASE)
    сдвиг = _сдвиг_дня(дм.group(1), lt) if дм else 0
    if час is None and not дм:
        # клиент не сказал когда — типовое «+4 часа от текущего»
        цель = _сдвиг_времени(lt, часов=_ПРОЗВОН_ЧЕРЕЗ_Ч)
        повод = "клиент времени не назвал: через %d часа" % _ПРОЗВОН_ЧЕРЕЗ_Ч
    else:
        ч, м = час if час else (0, 0)
        if час and ч == 0 and re.search(r"с\s+утра|утром|к\s+утру", окно, re.IGNORECASE):
            ч, м = [int(x) for x in (early.split(":") + ["0"])[:2]]
        цель = _сдвиг_времени(lt, день=сдвиг, час=ч, минута=м) if час \
            else _сдвиг_времени(lt, день=сдвиг,
                                час=int(early.split(":")[0]), минута=int(early.split(":")[1]))
        повод = "клиент просил набрать: %s" % (окно.strip()[:60] or "по его времени")
    цель = _в_приёмные_часы(цель, early, late)
    return ("%02d-%02d-%04d" % (цель.tm_mday, цель.tm_mon, цель.tm_year),
            "%02d:%02d" % (цель.tm_hour, цель.tm_min), повод)


# ⚠ «ДАВАЙТЕ ПОТОМ РЕШИМ» — ЭТО НЕ СОГЛАСИЕ, ХОТЯ «давайте» В НЁМ ЕСТЬ. Шаблон согласия
# ловит вежливые формы («да», «давайте», «хорошо»), и отказ, построенный на тех же словах,
# проходил как принятие окна. Проверка отрицания стоит ДО согласия и сильнее его.
_ОТКАЗ_ОТ_ОКНА_RX = re.compile(
    r"\bнет\b|\bне\s+(?:смогу|получится|подойд[её]т|удобно|буду|надо|нужно)|потом\s+реш|"
    r"позже\s+реш|\bне\s+сейчас\b|перенес|друг(?:ой|ое)\s+(?:день|время)|отмен",
    re.IGNORECASE)


def _это_согласие_на_окно(т):
    """Согласие клиента на предложенное окно, с проверкой отрицания."""
    if not т or _ОТКАЗ_ОТ_ОКНА_RX.search(т):
        return False
    return bool(_СОГЛАСИЕ_НА_ОКНО_RX.search(т))


def _окно_принято(messages):
    """Принял ли клиент окно, предложенное ботом, — по ВСЕЙ переписке, а не по последней реплике.

    ⚠ ДОГОВОРЁННОСТЬ И АДРЕС ПРИХОДЯТ В РАЗНЫЕ ХОДЫ И РАНЬШЕ НЕ ВСТРЕЧАЛИСЬ (снимок владельца
    27.08). Бот предложил «к 15:00-15:30», клиентка ответила «Да, было бы отлично», следующим
    ходом дала адрес — и `_время_согласовано`, глядя только на последнюю реплику, видела адрес
    и решала, что времени нет. Заявка выходила «прозвон завтра в 10:00» человеку, с которым уже
    договорились на пятницу.

    ⚠ ПОЧЕМУ НЕ ПРОСТО «ИСКАТЬ СОГЛАСИЕ ПО ВСЕЙ РЕЧИ»: тогда «да» на вопрос о модели телевизора
    зачлось бы согласием на окно, названное тремя ходами позже. Поэтому окно ищем в репликах
    БОТА, а согласие — только в том, что клиент написал ПОСЛЕ этого окна.

    Возвращает (принято, окно_текстом). Позднее вето клиента отменяет согласие.
    """
    окно, принято = "", ""
    for m in messages or []:
        т = (m.get("text") or "").strip()
        if not т:
            continue
        if m.get("role") != "client":
            найдено = _CLOCK_RX.search(т) or _SOFT_WINDOW_RX.search(т)
            if найдено and найдено.group(0) != окно:
                # ⚠ СБРАСЫВАЕМ ТОЛЬКО НА ДРУГОМ ОКНЕ. Бот подтверждает договорённость теми же
                # словами («буду у вас пятницу к 15:00-15:30»), и сброс на каждом упоминании
                # стирал согласие, данное ходом раньше, — ровно та поломка, что чинится.
                окно, принято = найдено.group(0), ""
            elif найдено:
                окно = найдено.group(0)
            continue
        if not окно:
            continue
        if _ВРЕМЯ_НЕ_РЕШЕНО_RX.search(т) or _ОТКАЗ_ОТ_ОКНА_RX.search(т):
            return False, ""
        if _КОГДА_НАБРАТЬ_RX.search(т) and not _ЗВОНОК_ПЕРЕД_ВИЗИТОМ_RX.search(т):
            return False, ""
        if not принято and _это_согласие_на_окно(т):
            принято = окно
    return bool(принято), принято


def _время_согласовано(client_all, last_client, посл_бот, окно_принято=None):
    """Есть ли ДОГОВОРЁННОСТЬ по времени. (bool, чем доказана).

    ⚠ ДОГОВОРЁННОСТЬ — ЭТО СЛОВО КЛИЕНТА, А НЕ ПРЕДЛОЖЕНИЕ БОТА. Три законных источника:
    клиент назвал час сам; назвал день в разговоре о приезде; принял окно, которое бот
    предложил в ПРОШЛОМ ходе (значит, клиент его прочитал). Всё остальное — не согласие.
    """
    lc = (last_client or "").strip()
    # вето сильнее любого подтверждения: последнее слово клиента отменяет прежние
    if _ВРЕМЯ_НЕ_РЕШЕНО_RX.search(lc):
        return False, "клиент отложил время"
    # ⚠ «ПОЗВОНИТЕ В 7 ВЕЧЕРА» — ЭТО ПРОЗВОН, А НЕ ЗАПИСЬ НА 19:00. Час назван, и
    # проверка «клиент назвал час» ниже засчитывала его договорённостью о ВИЗИТЕ:
    # мастер выезжал туда, где его ждали у телефона. Просьба набрать отменяет запись —
    # кроме звонка перед выездом, который с назначенным визитом прекрасно уживается.
    if _КОГДА_НАБРАТЬ_RX.search(lc) and not _ЗВОНОК_ПЕРЕД_ВИЗИТОМ_RX.search(lc):
        return False, "клиент просит звонок, а не визит"
    речь = client_all or ""
    if _ЧАС_ОТ_КЛИЕНТА_RX.search(речь):
        return True, "клиент назвал час"
    if _ДЕНЬ_ОТ_КЛИЕНТА_RX.search(речь) and _ПРИЕЗД_В_РЕЧИ_RX.search(речь):
        return True, "клиент назвал день"
    # ⚠ ОКНО БЕРЁМ ИЗ ПОСЛЕДНЕЙ РЕПЛИКИ БОТА, А НЕ ИЗ ВСЕЙ ПЕРЕПИСКИ. Иначе «да» на
    # вопрос про модель телевизора зачлось бы как согласие на окно, названное три хода назад.
    if посл_бот and (_CLOCK_RX.search(посл_бот) or _SOFT_WINDOW_RX.search(посл_бот)) \
            and _СОГЛАСИЕ_НА_ОКНО_RX.search(lc):
        return True, "клиент принял предложенное окно"
    # ⚠ СОГЛАСИЕ ЛИПКОЕ: принятое окно живёт до вето клиента, а не до следующей его реплики.
    # Считается по переписке (`_окно_принято`), поэтому переживает и перезапуск, и то, что
    # адрес пришёл отдельным ходом.
    if окно_принято:
        return True, "клиент принял предложенное окно (ходом раньше)"
    return False, ""


def _lead_ready(reply, client_all, has_phone, prior_bot="", has_addr=False,
                last_client="", посл_бот="", city="", окно_принято=None):
    """Готовность заявки: None | словарь с видом «полная» либо «прозвон».

    ⚠ ТЕЛЕФОН — НЕ ЗАЯВКА (правило владельца 26.08). Без адреса ехать некуда, без
    договорённости по времени визит назначать нельзя. Зато телефон И адрес без времени
    заявкой всё-таки являются — той, что уходит на ПРОЗВОН: диспетчер наберёт и
    подберёт окно голосом. Это ровно то, что делают живые операторы.
    """
    if not has_phone or not has_addr or not (reply or "").strip():
        return None
    окно_бота = _SLOT_IN_REPLY_RX.search(reply or "") or _SLOT_IN_REPLY_RX.search(посл_бот or "") \
        or _SLOT_IN_REPLY_RX.search(prior_bot or "")
    согласовано, чем = _время_согласовано(client_all, last_client, посл_бот,
                                          окно_принято=(окно_принято or [False, ""])[0])
    if согласовано:
        # окно берём из принятого клиентом, если оно известно: реплика ЭТОГО хода могла
        # окна не содержать вовсе (бот уже отговорил своё и молчит)
        _принятое = (окно_принято or [False, ""])[1]
        return {"вид": "полная", "телефон": True, "адрес": True,
                "окно": _принятое or (окно_бота.group(0) if окно_бота else ""), "почему": чем}
    дата, время, повод = _время_прозвона(client_all, last_client, city)
    return {"вид": "прозвон", "телефон": True, "адрес": True,
            "окно": "", "прозвон_дата": дата, "прозвон_время": время,
            "почему": повод}


# причины, при которых человека звать НЕ надо, хотя ход закрыт роутером: бот всё сказал сам
_NO_NOTIFY_KINDS = {"refuse", "junk"}


def _передать(res, reason):
    """Форс передачи человеку С НАЗВАННОЙ ПРИЧИНОЙ. Возвращает res для цепочек.

    ⚠ ОТДЕЛЬНАЯ ФУНКЦИЯ, А НЕ ДВА ПРИСВАИВАНИЯ НА МЕСТЕ. Причина забывалась ровно потому,
    что передача была одной строкой `res["handoff"] = True`, а поле причины жило в другом
    файле: семь форсов подряд её не ставили, и все они получали «тема не распознана».
    Пока это одна функция, забыть причину нельзя — её негде не передать.
    """
    res["handoff"] = True
    res["notify_reason"] = reason
    return res


def _contract(res, notify=None, reason=None, note=""):
    """Единый контракт ответа. Два ортогональных поля вместо смысла на пустой строке."""
    if not isinstance(res, dict) or res.get("error"):
        return res
    reply = (res.get("reply") or "").strip()
    if notify is None:
        # для веток, которые ещё не переведены явно, — прежняя семантика
        notify = bool(res.get("handoff") or res.get("to_operator"))
    if reason is None:
        fl = res.get("flag") or {}
        kind = fl.get("kind") if isinstance(fl, dict) else ""
        if notify:
            # ⚠ ПРИЧИНУ НАЗЫВАЕТ ТОТ, КТО ЗОВЁТ ЧЕЛОВЕКА. Модельный путь форсирует handoff в
            # семи местах (закрытый филиал, село за чертой, нет филиала направления, холод на
            # МНЧ, простыня с согласуемой темой, чистое согласование, пустой ответ шлюза) —
            # и ни одно из них не оставляло флага. Всё это падало в «else» и получало
            # unknown_topic: боевой журнал воронки за 20 дней — 194 передачи из 194 с пустым
            # флагом, то есть ярлык «тема не распознана» на каждой. Поле notify_reason —
            # прямой ответ вызывающего; карта по kind осталась для роутеров.
            reason = res.get("notify_reason") or {
                "complaint": "claim", "existing_client": "status",
                "call_request": "call_request", "call_made": "call_made", "soglas": "soglasovanie",
                "blocklist": "blocklist", "multi_account": "multi_account",
                "troll_exit": "troll_exit",
                "escalation": (fl.get("sub") if isinstance(fl, dict) else "") or "unknown_topic",
            }.get(kind, "unknown_topic")
        if kind in _NO_NOTIFY_KINDS and not res.get("to_operator"):
            notify, reason = False, None
    # ⚠ ТИРЕ СНИМАЕМ В ЕДИНСТВЕННОЙ ТОЧКЕ ВЫХОДА, А НЕ В СЕРЕДИНЕ (эталон 26.08).
    # `_no_dash` стоял внутри постпроцессора ДО того, как воронка дописывает свои пулы, а
    # в пулах тире было: «И номер оставьте — так проще договориться», «Оставьте номер —
    # согласую время». На эталонной выборке тире доехало до клиента в 4 ходах из 45 при
    # запрете владельца от 30.07. Чинить пулы по одному бессмысленно — они пишутся заново
    # каждую неделю; правило должно стоять там, где текст уходит наружу.
    reply = _no_dash(reply)
    # ⚠ ЕДИНСТВЕННОЕ ЧИСЛО — ЗДЕСЬ ЖЕ, ПО ТОЙ ЖЕ ПРИЧИНЕ, ЧТО И ТИРЕ: правило должно
    # стоять там, где текст уходит наружу, иначе очередной дописанный пул его обойдёт.
    reply = _в_единственном_числе(reply)
    res["reply"] = reply
    res["reply_text"] = reply
    res["notify_human"] = bool(notify)
    # ⚠ «лид готов» — ОТДЕЛЬНОЕ событие, не эскалация. Иначе очередь претензий утонет в
    # успешных заявках. Проставляется здесь же, чтобы у всех потребителей поле было одно.
    if res.get("lead_ready") is None:
        res["lead_ready"] = False
    res["escalation"] = escalation.event(reason, note) if (notify and reason) else None
    # старые флаги — производные, чтобы Пульт и LeadChat не заметили смены контракта
    res["handoff"] = bool(notify)
    res["to_operator"] = bool(notify and not reply)
    return res


#: Сколько ходов оператора терпит «первичный диалог». Замер боевых подсказок 25.08
#: (124 штуки): по-настоящему первичных — 26 (21 %), а в 81 случае (65 %) бот влезал
#: туда, где оператор уже вёл разговор три хода и больше. Владелец про это дословно:
#: «Боту не нужно влазить в каждый диалог, ему нужно работать только с первичными».
_МАКС_ХОДОВ_ОПЕРАТОРА = int(os.environ.get("LEADBOT_MAX_OPERATOR_TURNS", "2"))

#: Визит уже назначен — дальше боту говорить нечего. Замер: 13 подсказок из 124 (10 %)
#: выданы ПОСЛЕ того, как в переписке договорились о приезде; одна из них — «До встречи»
#: в ответ на «До встречи». Это чистый шум в ленте у диспетчера.
# ⚠ КАКАЯ РЕПЛИКА ТРЕБУЕТ ОТВЕТА, А КАКАЯ НЕТ — ЭТО ЗАМЕР, А НЕ ВКУС (правка владельца 27.08:
# «при создании заявки бот сам должен понимать, какой ответ требует ответа, а какой нет»).
# Замер по боевому корпусу: 2927 реплик клиента ПОСЛЕ назначенного визита, и для каждой видно,
# ответил ли живой оператор следующим ходом.
#
#   группа реплики        шт    живой отвечает
#   вопрос («?»)         611        61,5 %
#   длинное по делу      944        55,8 %
#   короткое, не акк     672        40,3 %
#   служебное             53        32,1 %
#   ПОДТВЕРЖДЕНИЕ        647        17,8 %      ← вот единственная группа, где молчат
#   ────────────────────────────────────────
#   всего               2927        44,6 %
#
# То есть на всё, кроме голого подтверждения, живой отвечает как минимум в 40 % случаев — это
# не «шум», это разговор. А на «хорошо / ок / спасибо / до встречи» он молчит в 82 % случаев.
# Отсюда правило: молчим ТОЛЬКО на подтверждении, на остальное отвечаем как обычно.
# ⚠ ДВА АККА ПОДРЯД — ТОТ ЖЕ ГОЛЫЙ АКК. «Хорошо понял», «Понял, хорошо», «Да, хорошо»
# гард не узнавал: он ждал ровно одно слово из списка. В живом корпусе это частая форма.
_НЕ_ТРЕБУЕТ_ОТВЕТА_RX = re.compile(
    r"^(?:(?:хорошо|ок|окей|да|понял|поняла|принял|ага|угу|ясно)[,\s]+)?"
    r"(?:хорошо|ок|окей|окэй|спасибо(?:\s+большое)?|благодарю|до\s+встречи|до\s+свидания|"
    r"да|ага|угу|договорились|отлично|супер|прекрасно|замечательно|понял|поняла|принял|принято|"
    r"жду|жд[уёе]м|ждем|буду\s+ждать|будем\s+ждать|хорошо[,\s]+спасибо|спасибо[,\s]+до\s+встречи|"
    r"ок[,\s]+спасибо|всё\s+верно|все\s+верно|подходит|устраивает|"
    # ⚠ «БЛАГОДАРЮ ВАС» И «ВСЕГО ДОБРОГО» МИМО СЛОВАРЯ (замер 27.08). «благодарю» тут было,
    # но обращение сразу за ним ломало якорь конца строки: живое «Благодарю Вас🤝» гард не
    # узнавал, и воронка дописывала к нему «Куда подъехать?».
    r"благодарю\s+(?:вас|вам)|всего\s+(?:доброго|хорошего)|хорошего\s+дня|"
    r"спасибо\s+(?:вам|большое\s+вам))"
    r"[\s.,!)?😊🙏👍🤝❤️✅🙂]*$", re.IGNORECASE)


def _не_требует_ответа(текст):
    """Реплика, на которую живой мастер обычно не отвечает: голое подтверждение или смайлик.

    ⚠ ОСТОРОЖНАЯ СТОРОНА — ОТВЕТИТЬ. Промолчать там, где клиент ждал ответа, дороже: он
    остаётся один на один с тишиной и уходит. Поэтому вопрос, цифра, новая просьба и вообще
    любая суть в реплике снимают признак, даже если рядом стоит «спасибо».
    """
    т = (текст or "").strip()
    if not т or "?" in т:
        return False
    if re.search(r"\d", т):
        return False                       # время, адрес, номер — это данные, их принимают
    # ⚠ ГОЛЫЙ СМАЙЛИК — САМОЕ ЧИСТОЕ ПОДТВЕРЖДЕНИЕ, И СЛОВА В НЁМ НЕТ. В корпусе «🤝» после
    # договорённости встретился 10 раз; отвечать на него нечего, а шаблон со словом его не ловит.
    if not re.search(r"[a-zA-Zа-яёА-ЯЁ]", т):
        return True
    return bool(_НЕ_ТРЕБУЕТ_ОТВЕТА_RX.match(т))


_ВИЗИТ_НАЗНАЧЕН_RX = re.compile(
    r"\bдо\s+встречи\b|\bзаписал\w*\s+(?:вас\s+)?на\b|\bбуду\s+у\s+вас\b|"
    r"\bжду\s+вас\b|\bдоговорились\b[^.!?\n]{0,20}\b(?:на|в)\s*\d|"
    r"\bподъеду\s+(?:сегодня|завтра|к\s*\d)|\bприеду\s+(?:сегодня|завтра|к\s*\d)|"
    # ⚠ ЖИВАЯ ФОРМА ИЗ БОЯ: «час полтора я у вас» — это назначенный приезд, сказанный
    # без слова «буду». Прошедшее время («я у вас был») сюда не попадает: там «был»
    # стоит сразу после, и требование будущего времени его отсекает.
    r"\bя\s+у\s+вас\b(?!\s*был)",
    re.IGNORECASE)


#: ⚠ РЕЖИМ ОБУЧЕНИЯ ОТКЛЮЧАЕТ ЗАСЛОН, И ТОЛЬКО ЕГО. Заслон правилен для боя (в 65 %
#: живых ходов бот влезал в чужой разговор), но он же не даёт РАЗОБРАТЬ бота: владелец
#: видит только первые ответы, а дальше «диалог уже ведёт оператор» — и всё. Разбор
#: должен показывать, как бот прошёл бы диалог ЦЕЛИКОМ. Включается переменной окружения,
#: то есть в бою выключен по умолчанию и включить его случайно нельзя.
_РЕЖИМ_ОБУЧЕНИЯ = os.environ.get("LEADBOT_TRAINING", "") not in ("", "0", "нет")


def _молчать_почему(norm, known=None):
    """Стоит ли боту вообще открывать рот. Пусто — говорим; строка — причина молчания.

    ⚠ ЭТО НЕ ФИЛЬТР КАЧЕСТВА ОТВЕТА, А РЕШЕНИЕ «МОЙ ЛИ ЭТО ДИАЛОГ». Замер 124 боевых
    подсказок 25.08 показал, что дело не в том, ЧТО бот пишет, а в том, ГДЕ он пишет:
    только 21 % ходов были первичными. Владелец: «сейчас как работает бот мне не
    нравится… ему нужно работать только с первичными диалогами».

    Молчание здесь — это НЕ отказ клиенту: ход уходит человеку (handoff), просто без
    подсказки. Панель на пустой ответ с handoff ничего в ленту не пишет
    (`engine.exec_ai_answer`: `elif needs_operator: LB_HANDOFF`).
    """
    if _РЕЖИМ_ОБУЧЕНИЯ:
        return ""          # разбор: бот проходит диалог целиком, молчание тут мешает
    # ⚠ СЧИТАЕМ ХОДЫ ЧЕЛОВЕКА, А НЕ СВОИ СОБСТВЕННЫЕ (снимок владельца 26.08).
    # Здесь стояло `m["role"] == "operator"` без разбора автора, а панель отдаёт свои же
    # ответы той же ролью. Итог: бот доходил до третьей СВОЕЙ реплики и объявлял, что
    # «оператор уже ведёт разговор» — сам себя. В диалоге со снимка к этой секунде были
    # телефон, адрес и согласованное время, то есть заявка на 100 %, и она не создалась
    # только потому, что хода не было вовсе. За неделю: 311 ходов из 1436 (21,7 %) ушли
    # человеку с этой причиной, а диалогов, где бот написал 3+ раза и человек не написал
    # ни разу, — 517 из 518.
    ходов = sum(1 for m in norm
                if m["role"] == "operator" and not m.get("свой") and (m["text"] or "").strip())
    if ходов > _МАКС_ХОДОВ_ОПЕРАТОРА:
        return "не первичный: оператор уже ведёт разговор (%d ходов)" % ходов
    # ⚠ ЗДЕСЬ СТОЯЛО ГЛУХОЕ «визит уже назначен — дальше ведёт человек», И ЭТО БЫЛО СЛИШКОМ
    # ГРУБО. Правило заводили по замеру «13 подсказок из 124 — шум после договорённости», и шум
    # оно убирало. Но вместе с ним убирало и разговор: замер по 2927 боевым репликам ПОСЛЕ
    # назначенного визита показал, что живой мастер отвечает на них в 44,6 % случаев, а на всё,
    # кроме голого подтверждения, — в 40-62 %. Плюс молчание здесь означало ПЕРЕДАЧУ человеку,
    # после которой панель бота в диалог больше не пускает.
    # Владелец 27.08: «при создании заявки бот сам должен понимать, какой ответ требует ответа,
    # а какой нет». Теперь решает не факт договорённости, а сама реплика — см. `_не_требует_ответа`
    # и ветку молчаливого удержания в `_run_relay_inner`.
    return ""


def _разметка_хода(res, norm, known=None):
    """Бот размечает СВОЙ ход: что сделал, чем решил и чего не хватает.

    ⚠ БЕЗ ВЫЗОВА МОДЕЛИ. Всё, что здесь написано, у бота уже есть: слой решения,
    стадия, собранные поля, причина передачи. Спрашивать об этом модель — платить за
    то, что и так известно, да ещё и получать её догадку вместо факта.

    ⚠ ЗНАЧЕНИЙ ПОЛЕЙ НЕ ПЕЧАТАЕМ, только имена: заметку видит вся смена, а в полях
    лежит телефон и адрес клиента (то же правило, что у «заявка собрана» в панели).

    Зачем это владельцу: в бою он видит только реплику и не знает, ПОЧЕМУ она такая.
    Разметка отвечает на «почему» одной строкой и годится в материал для обучения.
    """
    реплика = (res.get("reply") or "").strip()
    # номер СВОЕГО хода: реплики живого оператора здесь ни при чём, разметка про бота
    ходов = sum(1 for m in norm
                if m["role"] == "operator" and m.get("свой") and (m["text"] or "").strip())
    части = ["ход %d" % (ходов + 1), "решил: %s" % (res.get("model") or "?")]
    if not реплика:
        части.append("ПРОМОЛЧАЛ")
    else:
        сделал = []
        if _ОКНО_В_РЕПЛИКЕ_RX.search(реплика):
            сделал.append("предложил окно")
        if _ADDRQ_RX.search(реплика):
            сделал.append("спросил адрес")
        if phone_asked(реплика):
            сделал.append("попросил номер")
        if "?" in реплика:
            сделал.append("задал вопрос")
        части.append("сделал: %s" % (", ".join(сделал) if сделал else "ответил без шага"))
        части.append("длина %d зн. (у живых мастеров медиана 39)" % len(реплика))
    нет = res.get("missing") or []
    if нет:
        части.append("не хватает: %s" % ", ".join(str(x) for x in нет))
    esc = res.get("escalation") or {}
    if esc.get("reason"):
        части.append("человеку: %s" % esc["reason"])
    if res.get("lead_ready"):
        части.append("заявка собрана")
    return "🎓 Разметка бота — " + "; ".join(части)


def _run_relay_inner(messages, known=None):
    """Стейтлесс-ход для Пульта: клиент присылает ВСЮ историю [{role:'client'/'bot', text}].
    Ничего не держим на сервере — контекст не теряется даже при перезапуске."""
    norm = _cap_input([{"role": ("client" if m.get("role") == "client" else "operator"),
                        "text": (m.get("text") or ""),
                        # ⚠ ЧЬЯ РЕПЛИКА, И ПО УМОЛЧАНИЮ — НЕ НАША. Соблазн был вывести это из
                        # роли («bot» же значит бот), и он неверен: `role` у всех входов
                        # двузначная, и Пульт, и старая панель, и автоканал зовут «bot» ЛЮБУЮ
                        # реплику нашей стороны, включая написанную человеком. Пометить их
                        # своими значит снять заслон там, где он и нужен. Поэтому «своей»
                        # реплика становится только по прямому слову вызывающего.
                        "свой": bool(m.get("свой"))}
                       for m in (messages or []) if (m.get("text") or "").strip()])
    last_client = ""
    for m in reversed(norm):
        if m["role"] == "client":
            last_client = m["text"]
            break
    if not last_client:
        return {"error": "нет сообщения клиента"}
    # ⚠ ПРЕДМЕТ РАБОТЫ КЛИЕНТ НАЗЫВАЕТ ОДИН РАЗ. Шаблонный отказ считался по ПОСЛЕДНЕЙ
    # реплике, и через пять ходов после «заменой матрицы на ноутбуках занимаетесь?» бот
    # отвечал «матрицами не занимаюсь» — исключение про ноутбук не срабатывало, потому что
    # слова «ноутбук» в последней реплике уже не было (снимок владельца 27.08).
    # ⚠ ЗАГОЛОВОК ОБЪЯВЛЕНИЯ — САМЫЙ ЖЁСТКИЙ СИГНАЛ ПРЕДМЕТА, И ОН ЛЕЖАЛ БЕЗ ДЕЛА. В разбираемом
    # диалоге объявление называется «Ремонт и настройка компьютеров»: одного этого достаточно,
    # чтобы отказ по матрице ЖК ТВ к нему не относился. Кладём в предмет ТОЛЬКО потому, что
    # предмет умеет отказ снимать и не умеет создавать (см. докстринг check_refuse).
    речь_клиента = " ".join(m["text"] for m in norm if m["role"] == "client")
    речь_клиента = (речь_клиента + " " + ((known or {}).get("title") or "")).strip()

    # ⚠ ЗАСЛОН ПЕРЕД ВСЕМ ОСТАЛЬНЫМ, И ДО ВЫЗОВА МОДЕЛИ: если диалог не наш, ход не
    # стоит ни токенов, ни строки в ленте у диспетчера.
    # ⚠ ПОСЛЕ ДОГОВОРЁННОСТИ НЕ ВСЯКАЯ РЕПЛИКА ТРЕБУЕТ ОТВЕТА — И РЕШАЕТ ЭТО РЕПЛИКА, А НЕ ФАКТ
    # ДОГОВОРЁННОСТИ. «Хорошо», «Ок», «До встречи», смайлик — живой мастер молчит на них в 82 %
    # случаев (замер 2927 боевых реплик). Молчим и мы, но диалог ДЕРЖИМ: передача его потеряла бы
    # (панель второй раз бота не пускает), а клиент после «Ок» часто пишет ещё — и вот там ответ
    # нужен. Стоим ДО модели: платить за ход, который кончится молчанием, незачем.
    if _ВИЗИТ_НАЗНАЧЕН_RX.search(" \n".join(m["text"] for m in norm)) \
            and _не_требует_ответа(last_client):
        logbook.event("leadbot.silent_hold", повод="визит назначен, реплика ответа не требует",
                      last_client=(last_client or "")[:40])
        return {"reply": "", "to_operator": False, "handoff": False, "notify_reason": None,
                "flag": {"kind": "silent_hold",
                         "reason": "визит назначен, реплика ответа не требует"},
                "model": "локальный роутер (молчим, диалог держим)",
                "state": {"category": "unknown"}, "missing": list(prompt.REQUIRED_FIELDS),
                "ready": False, "done": False, "usage": None}
    _молчим = _молчать_почему(norm, known)
    if _молчим:
        return {"reply": "", "handoff": True, "notify_reason": "not_primary",
                # ⚠ ПРИЧИНУ ОБЯЗАН НЕСТИ И РАННИЙ ВОЗВРАТ (28.08). Событие эскалации
                # собирается в общем хвосте `_finish`, а роутеры возвращают словарь
                # напрямую — мимо него. Панель читает причину из `meta.escalation` и,
                # не найдя её, пишет в очередь «AI не уверен в ответе». По журналу
                # боевого сервера так подписано 311 случаев «не наш диалог» за две
                # недели: правильное поведение выглядело как ошибка ИИ, а оператор
                # сортирует очередь именно по причине.
                "escalation": escalation.event("not_primary", _молчим),
                "flag": {"kind": "not_primary", "reason": _молчим},
                "model": "локальный роутер (не наш диалог)",
                "state": {"category": "unknown"}, "missing": list(prompt.REQUIRED_FIELDS),
                "ready": False, "done": False, "usage": None}

    # РАННИЕ ВОЗВРАТЫ РОУТЕРОВ тоже не должны здороваться повторно: их шаблоны начинаются с
    # «Здравствуйте», и посреди переписки это мгновенный маркер бота (44 из 59 отказов не на
    # первом ходу). Модельный путь чистится ниже (_strip_greeting), роутеры — вот здесь.
    _bot_spoke = _мы_уже_здоровались(norm, known)

    def _greet(t):
        """Ранние возвраты роутеров ТОЖЕ проходят стилевой слой (STYLE-05).

        Раньше шаблоны отдавались клиенту в обход _no_dash/_humanize, и в чат уходило
        запрещённое тире («если что-то сломалось — пишите») и финальная точка — оба маркера,
        ради борьбы с которыми весь слой и написан. Теперь любой НОВЫЙ шаблон автоматически
        подчиняется правилам заказчика, а не надеется на внимательность автора."""
        if not t:
            return t
        t = _no_dash(t)
        t = _strip_greeting(t) if _bot_spoke else t
        return _humanize(t)

    # ЧЁРНЫЙ СПИСОК ПРОФИЛЕЙ (канал «Правила Авито», 11.06.2026): эти люди пишут НАМЕРЕННО,
    # чтобы оставить негативный отзыв на профиль. Правило дословно: «отвечать также этим людям
    # не нужно, полный игнор». Стоит ПЕРВЫМ — раньше любых тем и до вызова модели.
    bl = prefilter.check_blocklist((known or {}).get("visitor"))
    if bl:
        return {"reply": "", "to_operator": True, "handoff": True,
                "flag": {"kind": bl["kind"], "reason": bl["reason"]},
                "note": "Профиль из чёрного списка — не отвечаем, диалог человеку.",
                "model": "локальный фильтр", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "usage": None}
    # ОДИН ЧЕЛОВЕК НА >5 НАШИХ АККАУНТАХ (правило заказчика 01.08.2026 + «Правила Авито»):
    # 6-й и последующие диалоги можно сливать. Опознаём по хешу профиля Avito — он общий на
    # всех наших аккаунтах. До 5 включительно сливать НЕЛЬЗЯ, и пока номера нет — тоже нельзя.
    _cl_phone = prefilter.phones_in(" ".join(m["text"] for m in norm if m["role"] == "client"))
    ma = multi_account.check_multi_account(known, has_phone=bool(_cl_phone))
    if ma:
        return {"reply": "" if ma.get("silent") else prefilter.DEFLECT_REPLY,
                "to_operator": True, "handoff": True, "deflect": not ma.get("silent"),
                "flag": {"kind": ma["kind"], "reason": ma["reason"]},
                "note": "Профиль писал на %d наших аккаунтов — сливаем по правилу «>5»." % ma["accounts"],
                "model": "локальный фильтр", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "usage": None}
    # ⚠ ЖАЛОБА ВЫШЕ ОТКАЗА. Раньше отказ стоял первым и работал по тем же словам, что претензия
    # («полосы на экране», «разбил экран планшета»): недовольный клиент получал шаблон-отшив
    # «матрицами не занимаюсь» вместо тишины, к оператору диалог не помечался (to_operator не
    # выставлялся) — то есть бот сам провоцировал негативный отзыв на профиль, а человек об этом
    # не узнавал. Политика заказчика однозначна: претензия — ВСЕГДА человеку и молча.
    cmp = prefilter.check_complaint(last_client)
    if cmp:
        # ⚠ ОДИН МОСТИК НА ПРЕТЕНЗИИ ПОСЛЕ ВИЗИТА (решение 30.08 по хвосту №15c;
        # замер: живые закрывали такие сами в 97,8 %, их топ-ход — добор номера
        # обращения). Передача человеку ОСТАЁТСЯ немедленной — но клиент с жалобой
        # больше не смотрит в тишину: без обещаний и оправданий просим номер, по
        # которому человек поднимет историю. Мостик строго один: если номер уже в
        # чате или мостик уже звучал — прежнее молчание.
        _был_визит = bool(re.search(r"приезжал|был\s+мастер|после\s+(?:ремонта|визита|вашего)|"
                                    r"вы\s+(?:чинили|делали|ставили|приезжали)",
                                    (last_client or "") + " " + (речь_клиента or ""), re.IGNORECASE))
        _мостик = ""
        if (_был_визит and not prefilter.phones_in(речь_клиента or "")
                and "номер" not in " ".join(
                    m["text"] for m in norm if m["role"] != "client").lower()):
            _hm = int(hashlib.sha256((last_client or "").encode("utf-8")).hexdigest(), 16)
            _мостик = ["Номер, с которого обращались, подскажите — сейчас разберусь",
                       "Подскажите номер, с которого обращались, подниму историю",
                       "С какого номера оформляли, напишите — разберусь",
                       "Напишите номер обращения или телефон — гляну, что случилось",
                       "Номер телефона, с которого обращались, подскажите — проверю",
                       "Подскажите телефон, на который оформляли, — разберусь"][_hm % 6]
            logbook.event("leadbot.complaint_bridge")
        return {"reply": _мостик, "to_operator": True, "handoff": True,
                "flag": {"kind": cmp["kind"], "reason": cmp["reason"]},
                "model": "локальный роутер (жалоба%s)" % (", мостик" if _мостик else ", молча"),
                "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False, "usage": None}
    ref = prefilter.check_refuse(last_client, речь_клиента)
    if ref and ref.get("kind") == "soglas":
        # ⚠ 12.08: тема опознана отказным детектором, но регламент велит согласовывать,
        # а не отказывать (матрица, телефоны, заправка, спутниковое ТВ, батарейка, самокат).
        # Исход — согласование: удержание и человек, без пометки «отказ» в журнале.
        #
        # ⚠ 26.08 — И ТЕПЕРЬ МОЛЧА, как и всякое другое согласование (снимки 6 и 7 владельца).
        # Дословно: «Тут можно было не отвечать… из-за контекста тут заправка картриджа, и
        # писать так ради того, чтобы создать заявку, не нужно. Лучше на такое просто не
        # отвечать, если тут и так понятно, что заявка принимается по согласованию».
        # Ровно тот же довод, по которому 25.08 замолчала ветка `check_soglasovanie`: черновик
        # «сверюсь по графику» создавал видимость ответа, который диспетчер всё равно вычитывает.
        # На снимках это стоило прямого расхождения: один клиент написал на два наших аккаунта
        # и получил «сверюсь по графику» на одном и «лучше в сервис заправки обратиться» на
        # другом — то есть увод к конкуренту там, где отвечать было не нужно вовсе.
        return {"reply": "", "to_operator": True, "handoff": True,
                "flag": {"kind": "soglas", "sub": ref.get("sub"), "reason": ref["reason"]},
                "model": "локальный роутер (согласование по регламенту)",
                "state": {"category": "unknown"}, "missing": list(prompt.REQUIRED_FIELDS),
                "ready": False, "done": False, "usage": None}
    if ref:
        return {"reply": _greet(ref["draft"]), "deflect": True,
                "flag": {"kind": ref["kind"], "reason": ref["reason"]},
                "model": "локальный фильтр", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "handoff": True, "usage": None}
    _bot_blob = " ".join(m["text"] for m in norm if m["role"] == "operator")
    _cl_blob = " ".join(m["text"] for m in norm if m["role"] == "client")
    ex = prefilter.check_existing_client(last_client, bot_history=_bot_blob, all_client_text=_cl_blob)
    if ex:
        base = {"handoff": True, "flag": {"kind": ex["kind"], "reason": ex["reason"]},
                "model": "локальный роутер (уже наш клиент)", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False, "usage": None}
        if ex.get("silent"):
            base.update({"reply": "", "to_operator": True})
        else:
            base.update({"reply": _greet(ex["draft"])})
            if ex.get("to_operator"):        # мостик-реплика + всё равно человеку (статус/перенос)
                base["to_operator"] = True
        return base
    # ⚠ ГОЛОСОВОЕ БЕЗ ТЕКСТА — ОТВЕЧАЕМ ЧЕСТНО И БЕЗ МОДЕЛИ (24.08). Аудио бот не
    # понимает, и худший исход не «не расслышал», а «ответил по смыслу, которого не
    # слышал». Ноль информации на входе — платить за вызов модели нечем.
    #
    # ⚠ ЧЕЛОВЕКА ЗОВЁМ. Утром здесь стояло «не зовём: клиент сейчас напишет текстом» —
    # это было допущение, и замер боевой базы его опроверг в тот же день: из 258
    # голосовых без текста ответ текстом в следующие десять минут пришёл только на 124
    # (48%). Больше половины клиентов не пишут, и без человека такой диалог просто
    # умирает. Голосовых 4-23 в сутки — очередь этим не зальёшь.
    if prefilter.voice_only(last_client):
        return {"reply": _greet(prefilter.ГОЛОСОВОЕ_ОТВЕТ), "handoff": True,
                "notify_reason": "voice",
                "escalation": escalation.event("voice", "голосовое сообщение без текста"),
                "flag": {"kind": "voice", "reason": "голосовое сообщение без текста"},
                "model": "локальный роутер (голосовое)", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "usage": None}
    # ⚠ ЗВОНОК — ЭТО ПРОСЬБА О ЗВОНКЕ, ТОЛЬКО СИЛЬНЕЕ СЛОВ (24.08). В боевом диалоге клиент
    # набирал номер трижды (17:48, 20:32, 20:37), а чат в это время просил у него телефон и
    # подталкивал «Ну что, подскажете?». Ответ был предсказуем.
    #
    # Факт звонка до бота не доходил вовсе: системная запись отфильтровывается обоими путями
    # доставки истории, и ни один из пяти роутеров такую ситуацию не ловит. Теперь панель
    # передаёт `events`, а два набора подряд ведём тем же путём, что и «перезвоните»:
    # причина call_request, срок реакции 15 минут. Если звонки были отвечены, человек снимет
    # эскалацию первым же взглядом — это дешевле, чем клиент, которому не перезвонили.
    _звонков = int((known or {}).get("calls") or 0)
    # ⚠ ПОРОГ ОПУЩЕН С ДВУХ ЗВОНКОВ ДО ОДНОГО (слово владельца 25.08 по снимку с Губкиным).
    # Довод владельца дословно: «мы не знаем, сколько он говорил и дозвонился бы вообще —
    # это сможет узнать только оператор». После звонка бот отвечает вслепую: он не слышал
    # разговора и не знает, договорились ли уже. В том диалоге он на один звонок ответил
    # «Сразу сориентирую по мастеру и времени» — обещание за людей, которых не назначал.
    # Цена: на боевом корпусе ровно один звонок в 449 диалогах из 30 526 (1,5 %) — столько
    # ходов уйдёт человеку дополнительно. Против этого — клиент, которому не перезвонили.
    # ⚠ ПОРОГ ПЕРЕСМОТРЕН 26.08 ПО СЛОВУ ВЛАДЕЛЬЦА — И ЭТО ОТМЕНА МОЕГО ЖЕ РЕШЕНИЯ ОТ 25.08.
    # Тогда порог опустили с двух звонков до одного, довод был: «мы не знаем, сколько он
    # говорил и дозвонился бы вообще». Теперь владелец смотрит на это иначе и говорит прямо:
    # «люди могут позвонить и не дозвониться, поэтому мы можем спокойно такое отработать и
    # создать заявку». На снимке 26.08 клиент один раз звонил и спрашивал в чате «завтра
    # вечером сможете приехать посмотреть?» — живой рабочий вопрос, а бот на него промолчал.
    # Молчим теперь там, где разговор ВИДЕН: следы в переписке либо два и больше вызовов.
    _разговор_виден = bool(_РАЗГОВОР_БЫЛ_RX.search(_cl_blob or ""))
    if _звонков >= 2 or (_звонков >= 1 and _разговор_виден):
        # ⚠ МОЛЧА: любой ответ здесь ломает легенду частного мастера («передам коллеге»),
        # а о чём говорили по телефону, знает только оператор. Панель на пустой ответ с
        # handoff в ленту ничего не пишет.
        return {"reply": "", "handoff": True, "call_needed": True,
                # ⚠ ПРИЧИНА НАЗЫВАЕТ ТО, ЧТО БЫЛО: клиент ЗВОНИЛ, а не просил позвонить.
                # Со снимка владельца 26.08: в очереди висело «клиент просит позвонить»,
                # хотя в переписке он спрашивал, приедем ли завтра вечером.
                "notify_reason": "call_made",
                "escalation": escalation.event("call_made", "клиент звонил — нужен звонок оператора"),
                "flag": {"kind": "call_request",
                         "reason": ("клиент звонил %d раз(а)%s — нужен звонок оператора: "
                                    "о чём говорили, знает только он"
                                    % (_звонков, ", и разговор виден в переписке"
                                       if _разговор_виден else ""))},
                "model": "локальный роутер (клиент звонит)", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "usage": None}
    call = prefilter.check_call_request(last_client, all_client_text=_cl_blob)
    if call:
        return {"reply": _greet(call["draft"]), "handoff": True, "call_needed": True,
                "flag": {"kind": call["kind"], "reason": call["reason"]},
                "model": "локальный роутер (звонок оператора)", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False, "usage": None}
    # ВЫХОД ИЗ ТРОЛЛИНГА (правка заказчика 04.08): три реплики подряд не по делу и поломки нет —
    # вежливо прощаемся и больше не развлекаем. Диалог уходит человеку: вдруг это всё же клиент.
    _cl_texts = [m["text"] for m in norm if m["role"] == "client"]
    if prefilter.troll_exit(_cl_texts):
        return {"reply": _greet(prefilter.TROLL_EXIT_REPLY), "handoff": True, "deflect": True,
                "flag": {"kind": "troll_exit", "reason": "3 хода офтопа без поломки"},
                "model": "локальный роутер (выход из троллинга)",
                "state": {"category": "unknown"}, "missing": list(prompt.REQUIRED_FIELDS),
                "ready": False, "done": False, "usage": None}
    sog = prefilter.check_soglasovanie(last_client)
    if sog:
        # ⚠ НА СОГЛАСОВАНИЕ БОТ БОЛЬШЕ НЕ ОТВЕЧАЕТ (слово владельца 25.08: «бот зачем-то
        # пишет на согласы, когда понятно, что соглас — на такое лучше не отвечать»).
        # Раньше отдавался черновик «сверюсь по графику и вернусь с ответом»; решение
        # всё равно принимает филиал, а черновик создаёт видимость ответа и обязывает
        # диспетчера его вычитывать. Ход уходит человеку молча.
        return {"reply": "", "handoff": True,
                "flag": {"kind": sog["kind"], "sub": sog.get("sub"), "reason": sog["reason"]},
                "model": "локальный роутер (согласование)", "state": {"category": "unknown"},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False, "usage": None}
    # фильтр мусора — без шлюза. prior_content: был ли содержательный ход клиента ДО последнего
    _client = [m for m in norm if m["role"] == "client"]
    _prior_content = any(re.search(r"[a-zа-яё0-9]", m["text"], re.I) for m in _client[:-1])
    jk = prefilter.check_junk(last_client, prior_client_content=_prior_content)
    if jk:
        pol = jk["policy"]
        base = {"state": {"category": "unknown"}, "missing": list(prompt.REQUIRED_FIELDS),
                "ready": False, "done": False, "usage": None,
                "flag": {"kind": "junk", "sub": jk["sub"], "reason": jk["reason"]},
                "model": "локальный роутер (мусор: %s)" % jk["sub"]}
        if pol == "operator":
            if jk["sub"] == "insult_to_bot":
                # эмпатия впереди приглашения к делу; ротация по профилю (анти-копирка)
                jk = dict(jk, draft=prefilter.insult_draft((known or {}).get("visitor") or ""))
            # ⚠ было всегда пустым (правка заказчика 04.08): молчание в чате читается как игнор
            # и злит сильнее хамства. Есть заготовленная спокойная фраза — отдаём её, оператор
            # подхватывает диалог от того же лица.
            _d = jk.get("draft") or ""
            base.update({"reply": _greet(_d) if _d else "", "to_operator": True, "handoff": True})
        elif pol == "close":
            base.update({"reply": _greet(jk["draft"]), "deflect": True, "handoff": True})
        else:                                          # nudge / ignore_comply
            _d = jk["draft"]
            if jk["sub"] in ("greet_only", "bare_ping"):
                # голое приветствие: ротация формулировки по профилю (анти-отпечаток на 35 аккаунтах)
                _d = prefilter.greet_draft((known or {}).get("visitor") or "")
            base.update({"reply": _greet(_d), "handoff": False})
        return base
    # ⚠ МЕДИАПРИСТАВКА БЕЗ ДИАГНОЗА → ВОПРОС, А НЕ «ДА, СДЕЛАЮ» (боевой диалог 30.08,
    # Раменское: «Вы apple tv ремонтируете? что-то с программой» — модель пообещала
    # приём, а ремонт таких приставок согласуемый). Ремонт ясен — молчаливая передача
    # через _SOGLAS; настройка ясна — модель ведёт приём; неясно — спрашиваем, что
    # с ней, ничего не обещая. Повторно не спрашиваем: если бот уже задавал вопрос
    # о приставке, ход отдаём модели — у неё в плейбуке та же развилка.
    _probe = prefilter.media_stb_probe(last_client, seed=_соглас_сид(known))
    if _probe:
        _уже_спрашивал = any(
            "?" in (m.get("text") or "") and re.search(
                r"приставк|с\s+ней", m.get("text") or "", re.IGNORECASE)
            for m in norm if m.get("role") == "operator")
        if not _уже_спрашивал:
            _ptxt = _greet(_probe)
            if not _bot_spoke:
                _ptxt = "Здравствуйте\n" + _ptxt
            return {"reply": _ptxt, "handoff": False,
                    "flag": {"kind": "media_stb_probe",
                             "reason": "медиаприставка: намерение неясно, уточняем"},
                    "model": "локальный роутер (медиаприставка: уточнение)",
                    "state": {"category": "unknown"},
                    "missing": list(prompt.REQUIRED_FIELDS),
                    "ready": False, "done": False, "usage": None}
    res = suggest_reply(norm, known=known)
    if res.get("pass_to_operator"):   # нестандартный/непонятный — молча оператору, без ответа
        return {"reply": "", "to_operator": True, "handoff": True,
                "notify_reason": "unknown_topic",
                "escalation": escalation.event("unknown_topic",
                                               "нестандартный вопрос — передаю оператору"),
                "note": "Нестандартный вопрос — передаю оператору (без ответа клиенту).",
                "state": {"category": res.get("category")},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "model": res.get("model"), "usage": res.get("usage")}
    # ⚠ ПУСТОЙ ОТВЕТ МОДЕЛИ = ДИАЛОГ ЧЕЛОВЕКУ, А НЕ ПУСТОЙ ПУЗЫРЬ. claude_api.first_tool_input
    # возвращает None, если tool_use-блока нет (обрыв по max_tokens): тогда reply пустой, а
    # pass_to_operator False — и Пульт пушил пустой пузырь бота: ни ответа клиенту, ни пометки
    # оператору, лид умирал молча. В run_turn такой фолбэк есть с самого начала.
    if not (res.get("reply") or "").strip():
        # ⚠ «НЕЧЕГО СКАЗАТЬ» — ЭТО НЕ «ОТДАТЬ ДИАЛОГ» (снимок владельца 27.08). Клиент написал
        # «Ок», модель промолчала — и это правильно, говорить было нечего. А бот передал диалог
        # менеджеру, и вернуться в него уже НЕ МОГ: панель не пускает бота второй раз
        # (`bot_entry_block`: «handoff_done — бот уже отдал диалог человеку»). То есть на
        # вежливом «Ок» диалог терялся для бота навсегда, вместе с заявкой, которую он собрал бы,
        # когда клиент напишет «я дома». Владелец: «можно было подержать его у себя».
        #
        # ⚠ ОТЛИЧИТЬ ОСОЗНАННОЕ МОЛЧАНИЕ ОТ ПОЛОМКИ НАДЁЖНО НЕЛЬЗЯ, и я не притворяюсь, что
        # умею. Правило написано под ПОЛОМКУ: `first_tool_input` отдаёт None при обрыве по
        # max_tokens, и тогда человек нужен. Поэтому молчим и остаёмся только там, где молчание
        # очевидно уместно: последнее слово клиента — вежливое подтверждение без сути («ок»,
        # «хорошо», «спасибо», «понял»). Во всех прочих случаях пустой ответ по-прежнему значит
        # поломку и зовёт человека.
        # Диалог при этом не повисает: шаг уходит на `next`, а это ожидание клиента со своим
        # таймаутом — не ответит, диалог штатно уедет человеку по нему.
        if _ПУСТАЯ_РЕПЛИКА_RX.match((last_client or "").strip()):
            logbook.event("leadbot.silent_hold", last_client=(last_client or "")[:40])
            return {"reply": "", "to_operator": False, "handoff": False,
                    "notify_reason": None,
                    "flag": {"kind": "silent_hold",
                             "reason": "клиенту нечего ответить — молчим и остаёмся в диалоге"},
                    "model": "локальный роутер (молчим, диалог держим)",
                    "state": res.get("state") or {"category": res.get("category")},
                    "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                    "usage": res.get("usage")}
        # ⚠ ТЕЛЕФОН В РЕПЛИКЕ — ТИШИНА ЗАПРЕЩЕНА (хвост №2 аудита, три боевых случая:
        # клиент присылает номер — самый горячий ход воронки — и получает пустоту до
        # прихода человека). Передача человеку остаётся, но клиенту уходит квитанция.
        _квит = ""
        if prefilter.phones_in(last_client or ""):
            _hq = int(hashlib.sha256((last_client or "").encode("utf-8")).hexdigest(), 16)
            _квит = ["Записал номер, наберу вас",
                     "Принял номер, свяжусь с вами",
                     "Номер записал, на связи",
                     "Записал, наберу чуть позже",
                     "Принял, номер записал",
                     "Номер у меня, свяжусь"][_hq % 6]
            logbook.event("leadbot.silent_phone_receipt")
        return {"reply": _квит, "to_operator": True, "handoff": True,
                "notify_reason": "model_silent",
                "escalation": escalation.event("model_silent",
                                               "модель не ответила — клиенту не ушло ничего"),
                "note": "Модель не вернула ответ — передаю оператору.",
                "state": {"category": res.get("category")},
                "missing": list(prompt.REQUIRED_FIELDS), "ready": False, "done": False,
                "model": res.get("model"), "usage": res.get("usage")}
    # длинная простыня с согласуемой темой: модель через раз «принимает» кондиционер — handoff
    # форсируем детерминированно (заявка в любом случае уйдёт через человека)
    if res.get("reply") and len(last_client) > 180 and prefilter.soglas_topic(last_client):
        _передать(res, "soglasovanie")
    # ЗА ЧЕРТОЙ ГОРОДА (село/деревня/СНТ/посёлок/дача) = согласование с филиалом независимо от
    # источника (регламент 30.07). Модель без этого «берёт» такую заявку: правила направления
    # («мебель собираем») в промпте сильнее территориальной оговорки — форсируем кодом.
    # Города-спутники сюда НЕ попадают: там строгий признак не срабатывает, их принимаем сами.
    # ЗАКРЫТЫЙ ФИЛИАЛ (Элиста, Петрозаводск БТ — объявления КЦ): заявки не принимаем вообще.
    # Клиенту ничего не обещаем, диалог уходит человеку.
    _closed = territory.is_closed((known or {}).get("city"))
    if _closed and res.get("reply"):
        _передать(res, "soglasovanie")
        res["reply"] = _greet(prefilter.soglas_reply(_соглас_сид(known)))
        res["note"] = "Филиал закрыт: %s" % _closed
    _client_all_txt = " ".join(m["text"] for m in norm if m["role"] == "client")
    # ⚠ ПРОВЕРЯЕМ ПОМЕССАЖНО, а не по склейке: в склеенной речи «…не плотно села» + «Левый берег»
    # даёт ложное «села Левый». Замер 46 315 диалогов: склейка не даёт НИ ОДНОГО честного
    # срабатывания сверх помессажного, зато рождает ложные. _client_all_txt ниже нужен far_trip.
    if res.get("reply") and (any(territory.settlement_outside(m["text"], (known or {}).get("city"))
                                 for m in norm if m["role"] == "client")
                             or _за_чертой_по_карте(norm, (known or {}).get("city"))):
        # ⚠ ДАЛЬНИЙ ВЫЕЗД КП (правило заказчика 01.08.2026) СИЛЬНЕЕ этого форса: село в 36 км от
        # филиала мы принимаем САМИ. Без этой проверки форс отправлял бы на согласование ровно те
        # заявки, ради которых правило и вводилось. На МНЧ, БТ и на теме ТВ far_trip молчит.
        _ft = territory.far_trip(_geo_text(norm), (known or {}).get("city"),
                                 (known or {}).get("direction"), _client_all_txt)
        if not _ft:
            _передать(res, "soglasovanie")
            # ⚠ ПРИЗНАК ЛИПКИЙ: он считается по всей речи клиента, поэтому одно слово из первого
            # хода подменяло КАЖДЫЙ следующий ответ одной и той же строкой (скан корпуса: 779
            # ходов в 153 диалогах из 6375). Дальше клиент диктует адрес и телефон — их надо
            # принять живым ответом. Но и молча отпускать модель нельзя: handoff у нас всего лишь
            # чип в пульте (ui/operator.html), отправку он не блокирует, а без форса модель такую
            # заявку «берёт». Поэтому отписку ПОВТОРЯЕМ ТОЛЬКО когда модель что-то ОБЕЩАЕТ —
            # часы, «завтра/сегодня», «запишу». handoff при этом остаётся на каждом ходу.
            _said = "по графику сверюсь" in _bot_blob.lower()
            _promise = bool(_CLOCK_RX.search(res["reply"]) or _BOOKED_REPLY_RX.search(res["reply"])
                            or _VAGUE_TIME_RX.search(res["reply"]))
            if not prefilter.check_soglasovanie(last_client):
                if not _said:
                    res["reply"] = _greet(prefilter.soglas_reply(_соглас_сид(known)))
                elif _promise:
                    # отписка уже была — не повторяем её дословно (роботизм),
                    # квитируем данные без обещания времени (как у холодильника на МНЧ)
                    res["reply"] = _greet("Принял. Гляну по месту, что выходит, и отвечу вам отдельно")
    # ГОРОДА НЕТ В СПРАВОЧНИКЕ ЭТОГО НАПРАВЛЕНИЯ (Воронеж на БТ и т.п.) = СОГЛАСОВАНИЕ.
    # Модель обещала «через два-два с половиной часа» вопреки территории (разбор 02.08) —
    # форсим кодом по образцу села: первый раз сверка, дальше квитанция без обещаний.
    # направление — по СУТИ задачи (решение заказчика 02.08), метка объявления — запасной
    _тексты_кл = [m["text"] for m in norm if m["role"] == "client"]
    _dir_known = prefilter.lock_direction(_тексты_кл, (known or {}).get("direction") or "")
    # ⚠ ХОЛОД В ГОРОДЕ БЕЗ ФИЛИАЛА БТ — ЗАЯВКА МНЧ ПО СОГЛАСОВАНИЮ (регламент, раздел МНЧ
    # «Бытовая техника»; решение владельца 18.08, вариант «C»). Раньше такой лид оставался
    # в БТ: клиент слышал «сверюсь по графику», а карточка ложилась в базу, где его города
    # нет — то есть не создавалась вовсе. Теперь направление МНЧ (там филиал есть), но
    # согласование с филиалом обязательно: обещать время нельзя, пока филиал не подтвердил.
    _город_кл = (known or {}).get("city") or ""
    _dir_known = _направление_по_городу(_dir_known, _тексты_кл, _город_кл)
    if _холод_в_мнч(_dir_known, _тексты_кл, _город_кл):
        _dir_known = "mnc"
        _передать(res, "soglasovanie")
        if "по графику сверюсь" not in _bot_blob.lower():
            res["reply"] = _greet(prefilter.soglas_reply(_соглас_сид(known)))
        elif bool(_CLOCK_RX.search(res["reply"]) or _BOOKED_REPLY_RX.search(res["reply"])
                  or _VAGUE_TIME_RX.search(res["reply"])):
            res["reply"] = _greet("Принял. Гляну по месту, что выходит, и отвечу вам отдельно")
        res["note"] = ("Холодильник в городе без филиала БТ — заявка МНЧ "
                       "по согласованию с филиалом (регламент)")
    if res.get("reply") and _dir_known and (known or {}).get("city") \
            and territory.no_filial((known or {}).get("city"), _dir_known):
        _передать(res, "soglasovanie")
        _said_nf = "по графику сверюсь" in _bot_blob.lower()
        _promise_nf = bool(_CLOCK_RX.search(res["reply"]) or _BOOKED_REPLY_RX.search(res["reply"])
                           or _VAGUE_TIME_RX.search(res["reply"]))
        if not _said_nf:
            res["reply"] = _greet(prefilter.soglas_reply(_соглас_сид(known)))
            res["note"] = "В городе нет филиала этого направления — согласование"
        elif _promise_nf:
            res["reply"] = _greet("Принял. Гляну по месту, что выходит, и отвечу вам отдельно")
            res["note"] = "В городе нет филиала этого направления — согласование"
    # ЧИСТОЕ СОГЛАСОВАНИЕ: отписка уже звучала, а модель обещает время/запись — «подъеду в
    # течение часа-полутора» после адреса на кронштейне (разбор заказчика 02.08, диалог 17).
    # Голое обещание меняем на квитанцию. ⚠ СМЕСЬ ЩАДИМ: если в самой реплике назван
    # принимаемый ПРЕДМЕТ («шкаф соберу, завтра к 10») — время законно для принятой части.
    if res.get("reply") and "по графику сверюсь" in _bot_blob.lower() \
            and prefilter.soglas_topic(_client_all_txt) \
            and bool(_CLOCK_RX.search(res["reply"]) or _BOOKED_REPLY_RX.search(res["reply"])
                     or _VAGUE_TIME_RX.search(res["reply"])) \
            and not prefilter._ACCEPT_OBJ_RX.search(res["reply"].lower()):
        res["reply"] = _greet("Принял. Гляну по месту, что выходит, и отвечу вам отдельно")
        _передать(res, "soglasovanie")
    # (форс «холодильник на МНЧ» удалён 02.08: направление теперь по СУТИ задачи —
    # холодильник всегда БТ, приём или сверку решает территория БТ через no_filial выше)
    # СОГЛАСУЕМАЯ ПОЗИЦИЯ БЕЗ ШАБЛОНА (смешанный список или простыня >180) — ФОРСИМ handoff кодом.
    # Подсказку в промпте сильная модель отрабатывает («по банковскому сверюсь»), а Haiku на живой
    # пробе 01.08 её проигнорировала и пообещала весь список. Реплику НЕ подменяем: шаблон похоронил
    # бы принимаемые позиции. Задача форса одна — чтобы такой диалог гарантированно увидел человек.
    if res.get("reply") and not prefilter.check_soglasovanie(last_client) \
            and prefilter.soglas_topic(last_client):
        _передать(res, "soglasovanie")
    if _мы_уже_здоровались(norm, known):   # бот уже здоровался — убираем повторное «Здравствуйте»
        res["reply"] = _strip_greeting(res.get("reply", ""))
    st = dict(res.get("state") or {})
    st["category"] = res.get("category")
    res["state"] = st
    res["missing"] = _missing(st)
    _bot_turns = sum(1 for m in norm if m["role"] == "operator")
    res["timing"] = _timing_plan(last_client, res.get("reply"), turn_index=_bot_turns)
    # ЗАЯВКА — ПОСЛЕ ВСЕХ ФОРСОВ (18.08). До этой точки ответ ещё мог смениться
    # на «сверюсь по графику» (закрытый филиал, чужое направление, соглас-тема),
    # и заявка оказалась бы ложной.
    # ⚠ ЛЮБАЯ ПЕРЕДАЧА ЧЕЛОВЕКУ УБИВАЛА УЖЕ ПОСЧИТАННУЮ ЗАЯВКУ. Здесь стояло
    # `and not res.get("handoff")`, а `handoff` значит «нужен человек», а не «заявки нет»:
    # форс передачи стоит в семи местах модельного пути (закрытый филиал, село за чертой,
    # холод на МНЧ, пустой ответ шлюза…), и на всех семи собранная заявка выбрасывалась.
    # Теперь смотрим ПРИЧИНУ: заявку не создаём только там, где её заводит человек.
    _причина_передачи = str(res.get("notify_reason") or "")
    if res.pop("_lead_pending", False) and res.get("lead") \
            and _причина_передачи not in _БЕЗ_ЗАЯВКИ:
        if "по графику сверюсь" not in (res.get("reply") or "").lower():
            _kr_after = {k: (known or {}).get(k)
                         for k in ("visitor", "city", "title", "direction", "persona",
                                   "partner", "white", "origin", "review_url")}
            _maybe_autocreate(res, _kr_after, known, norm)
    _log_funnel(res, norm)
    return res


def _log_funnel(res, norm):
    """Лог воронки (ТЗ п.4, 02.08.2026): одна строка на ход БЕЗ персональных данных —
    только флаги наличия полей. Динамика конверсии считается по последним ходам диалогов:
    analysis/funnel_log.jsonl → доля done/телефона до и после правок."""
    try:
        st = res.get("state") or {}
        fl = res.get("flag")
        rec = {"t": _now(),
               "turns": sum(1 for m in norm if m.get("role") == "client"),
               "phone": bool((st.get("phone") or "").strip()),
               "addr": bool((st.get("address") or "").strip()),
               "time": bool((st.get("preferred_time") or "").strip()),
               "done": bool(res.get("done")), "handoff": bool(res.get("handoff")),
               "cached": bool(res.get("cached")),
               "flag": (fl.get("kind", "") if isinstance(fl, dict) else str(fl or ""))}
        with open(os.path.join(ROOT, "analysis", "funnel_log.jsonl"), "a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    except Exception:
        pass


def compare_dialog(messages, known=None, max_points=6):
    """Для обучения: на каждый ход клиента — что сказал ОПЕРАТОР vs что предложил бы БОТ."""
    pairs = []
    i, n = 0, len(messages)
    while i < n and len(pairs) < max_points:
        if messages[i].get("role") == "client":
            j = i
            while j < n and messages[j].get("role") == "client":
                j += 1
            op = []
            k = j
            while k < n and messages[k].get("role") == "operator":
                if messages[k].get("text"):
                    op.append(messages[k]["text"])
                k += 1
            # ПРОД-путь (с локальными роутерами: скупка/жалоба/соглас/мусор...), а не голый
            # suggest_reply — иначе сравнение с оператором врёт (роутерные кейсы шли к модели)
            sug = run_relay(messages[:j], known=known)
            client_block = "\n".join(m.get("text", "") for m in messages[i:j] if m.get("text"))
            pairs.append({
                "client": client_block,
                "operator": "\n".join(op),
                "bot": sug.get("reply", ""),
                "model": sug.get("model"),
            })
            i = max(k, j)
        else:
            i += 1
    return pairs


# ---- СОПРЯЖЕНИЕ С LEADCHAT ------------------------------------------------
# Один эндпоинт под протокол шага `ai_answer` движка сценариев LeadChat. Контракт,
# примеры и готовый адаптер для их стороны — в docs/ИНТЕГРАЦИЯ-LEADCHAT.md.
# ── НАСТРОЙКА ГОРОДОВ ИЗ ПАНЕЛИ (просьба заказчика 15.08: «править в реальном
# времени») ── правки живут в data/city_overrides.json, filials перечитывает файл
# по mtime — рестарт не нужен, выкатка файл не трогает (.gitignore).
def _cities_overview(direction):
    import filials
    d = direction if direction in ("kp", "mnc", "bt") else "kp"
    ovr_all = filials._overrides()
    ovr = dict(ovr_all.get("any") or {})
    ovr.update(ovr_all.get(d) or {})
    rows, seen = [], set()

    def _base_status(name):
        n = filials._norm(name)
        try:
            import territory
            if n in {filials._norm(x) for x in territory.CLOSED_FILIALS}:
                return "closed", "закрыт (правило заказчика)"
        except Exception:
            pass
        if d == "kp" and n in {filials._norm(x) for x in filials.SUSPENDED_KP}:
            return "closed", "пометка «-» в базе"
        sat = filials.SAT[d].get(name) or {filials._norm(k): v
                                           for k, v in filials.SAT[d].items()}.get(n)
        if sat:
            return "satellite", "справочник"
        return "main", "справочник"

    for name in list(filials.MAIN[d]) + list(filials.SAT[d]):
        n = filials._norm(name)
        if n in seen:
            continue
        seen.add(n)
        status, source = _base_status(name)
        parent = filials.SAT[d].get(name) or ""
        rec = ovr.get(n)
        if isinstance(rec, dict) and rec.get("status"):
            status, source = rec["status"], "настройка"
            parent = rec.get("parent") or ""
        rows.append({"city": name, "status": status, "parent": parent, "source": source})
    for n, rec in ovr.items():                  # города, добавленные только правкой
        if n in seen or not isinstance(rec, dict) or not rec.get("status"):
            continue
        rows.append({"city": n.title(), "status": rec["status"],
                     "parent": rec.get("parent") or "", "source": "настройка"})
    rows.sort(key=lambda r: r["city"])
    return {"dir": d, "cities": rows}


def _cities_save(body):
    import filials
    d = (body or {}).get("dir") or ""
    city = ((body or {}).get("city") or "").strip()
    status = ((body or {}).get("status") or "").strip()
    parent = ((body or {}).get("parent") or "").strip()
    if d not in ("kp", "mnc", "bt", "any"):
        return "направление должно быть kp / mnc / bt / any"
    if not city:
        return "нет города"
    if status not in ("", "main", "satellite", "closed"):
        return "статус: main / satellite / closed / пусто (снять правку)"
    if status == "satellite" and not parent:
        return "спутнику нужен родитель (parent)"
    data = dict(filials._overrides() or {})
    sect = dict(data.get(d) or {})
    key = filials._norm(city)
    if status:
        sect[key] = {"status": status, **({"parent": parent} if parent else {})}
    else:
        sect.pop(key, None)
    data[d] = sect
    tmp = filials._OVR_PATH + ".tmp"
    os.makedirs(os.path.dirname(filials._OVR_PATH), exist_ok=True)
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    os.replace(tmp, filials._OVR_PATH)          # атомарно: панель не увидит полфайла
    return ""


LEADCHAT_PATH = "/api/leadchat/answer"


def leadchat_answer(body):
    """Ответ для LeadChat: всегда валидный JSON и всегда в срок.

    Три правила, все из их движка (он не ретраит и по таймауту молча уводит в handoff):
      1. Не успели за LEADBOT_ANSWER_TIMEOUT_S — сами отдаём «нужен оператор», не
         дожидаясь их секундомера. Диалог не зависает, решение принимаем мы.
      2. Любое исключение — тоже «нужен оператор», а не 500: пятисотка для клиента в
         чате выглядит так же, как молчание.
      3. Повтор с тем же request_id отдаёт прежний ответ, не тратя вызов модели и не
         присылая клиенту вторую реплику."""
    t0 = time.time()
    try:
        messages, known, rid, warn = leadchat.parse_request(body)
    except ValueError as e:
        return leadchat.unavailable("плохой запрос: %s" % e,
                                    ms=int((time.time() - t0) * 1000)), 400
    except Exception as e:                           # noqa: BLE001 — наружу только «оператор»
        # ⚠ РАЗБОР ЗАПРОСА ТОЖЕ ОБЯЗАН ЧЕМ-ТО ОТВЕТИТЬ (этап 5). Ловился один ValueError,
        # а на неожиданной форме поля (блочный content) летел AttributeError — мимо этой
        # ветки, мимо всего обработчика HTTP, и наружу не уходило НИЧЕГО: ни ответа, ни
        # кода, ни строки журнала. Правило 2 этой функции («любое исключение — оператор,
        # а не 500») не работало ровно потому, что беда случалась раньше него.
        _ms = int((time.time() - t0) * 1000)
        logbook.refused(logbook.причина(e), source="leadchat", ms=_ms)
        return leadchat.unavailable("плохой запрос: %s" % logbook.причина(e), ms=_ms), 400

    was = leadchat.cached(rid)
    if was is not None:
        # Повтор того же request_id. Записываем отдельным событием: иначе в
        # журнале он выглядит как второй ответ клиенту, которого не было.
        logbook.event("leadbot.repeat", request_id=rid, source="leadchat")
        return was, 200

    box = {}
    # Метка этого хода. Нить ставит её СЕБЕ (thread-local пишется только изнутри
    # нити), а мы снаружи держим ту же ссылку и можем объявить ход брошенным.
    метка = {"брошен": False}

    def _work():
        _ХОД.метка = метка
        _ХОД.начало = time.time()
        try:
            box["res"] = run_relay(messages, known=known)
        except Exception as e:                       # noqa: BLE001 — наружу только «оператор»
            # ГДЕ именно упало — в самой строке ошибки (18.08). Без места
            # разбор начинался с чтения всего конвейера: «TypeError: 'set'
            # object is not subscriptable» ничего не говорит о том, в каком
            # из сорока шагов это случилось. Берём последний кадр НАШЕГО кода
            # (помощник живёт в logbook: тем же местом пользуется автоканал).
            box["err"] = logbook.причина(e)

    th = threading.Thread(target=_work, daemon=True)
    th.start()
    th.join(leadchat.timeout_s())
    ms = int((time.time() - t0) * 1000)

    if th.is_alive():
        # Поток дорабатывает сам (ответ модели попадёт в кэш ответов и пригодится
        # на следующем ходу), но клиента дальше ведёт человек.
        # Решение отдать диалог человеку принимаем МЫ и осмысленно — до того,
        # как сработает секундомер LeadChat. В журнале это обязано отличаться
        # от «упали»: там причина в нас, здесь — в том, что не успели.
        # ⚠ И ЗАЯВКУ ЭТОТ ХОД БОЛЬШЕ НЕ СОЗДАЁТ (этап 5). Ответ, который нить всё-таки
        # досчитала, клиенту НЕ ушёл — а вместе с ним не ушло и предложенное время. Заявка
        # же собиралась именно из него: в CRM ложилась карточка с визитом на час, о котором
        # с клиентом не договаривались, да ещё и вторая — от человека, ведущего этот диалог.
        метка["брошен"] = True
        logbook.refused("таймаут %.0f c" % leadchat.timeout_s(), source="leadchat", request_id=rid, ms=ms)
        return leadchat.unavailable("таймаут %.0f c" % leadchat.timeout_s(), rid, ms), 200
    if "err" in box:
        logbook.refused(box["err"], source="leadchat", request_id=rid, ms=ms)
        return leadchat.unavailable(box["err"], rid, ms), 200

    out = leadchat.to_answer(box.get("res"), warnings=warn, ms=ms, request_id=rid)
    # ГЛАВНАЯ СТРОКА ЖУРНАЛА — про ГОТОВЫЙ ответ, а не про промежуточный
    # результат: журнал обязан говорить о том, что увидел собеседник.
    logbook.answered(out, source="leadchat", request_id=rid, ms=ms, dialog_len=len(messages))
    # ⚠ КОРОТКИЙ КОНТЕКСТ — ОТДЕЛЬНАЯ СТРОКА ЖУРНАЛА (19.08). Один-два хода на входе
    # означают, что бот отвечает вслепую; по замеру это каждый седьмой вызов. Пишем
    # роли и длины пришедших реплик, чтобы отличить «LeadChat прислал мало» от «наш
    # разбор выбросил»: без этого спор двух сервисов не решается никак.
    # ⚠ ПИШЕМ НЕ КАЖДЫЙ КОРОТКИЙ ВХОД, А ПОДОЗРИТЕЛЬНЫЙ. Первое обращение клиента —
    # это законная одна реплика, и строка на каждую такую превращает журнал в шум
    # (7 записей за 20 минут, все — новые диалоги). Беда выглядит иначе: в диалоге
    # УЖЕ шёл разговор (есть реплики нашей стороны), а контекста пришло два хода.
    _наших = sum(1 for m in messages if m.get("role") != "client")
    if len(messages) <= 2 and _наших:
        logbook.event("leadbot.short_context", request_id=rid, source="leadchat",
                      реплик=len(messages),
                      роли=[m.get("role") for m in messages],
                      длины=[len((m.get("text") or "")) for m in messages],
                      предупреждения=warn or [])
    # ⚠ ТЕНЕВОЙ ЖУРНАЛ — ПОСЛЕ ответа и вне его пути. Пишем то, что реально ушло, и
    # ничего не ждём: наблюдение не имеет права ни задержать ход, ни его уронить.
    shadow.ход(messages, known, box.get("res"), out=out, ms=ms,
               стадия=метка.get("стадия", ""), источник="leadchat")
    leadchat.remember(rid, out)
    return out, 200


# ---- HTTP ----------------------------------------------------------------
def _panel_token():
    """Секрет доступа снаружи: env LEADBOT_PANEL_TOKEN (VPS) или panel_token в config.json."""
    return (os.environ.get("LEADBOT_PANEL_TOKEN") or claude_api.config().get("panel_token") or "").strip()


class Handler(BaseHTTPRequestHandler):
    server_version = "LeadBot/0.1"

    # ── доступ (VPS, сессия 42f): наружу ВЕСЬ сервер закрыт секретной ссылкой ──
    # /panel/<токен> ставит куку и пускает; без неё удалённым — 403 на ЛЮБОЙ путь
    # (иначе /api/message наружу жёг бы ключ API, а /relay показывал бы переписку).
    # С самой машины (и без прокси-заголовка) всё открыто, как дома.
    def _is_remote(self):
        # за Caddy запрос приходит с 127.0.0.1 — удалённость выдаёт X-Forwarded-For
        peer = (self.client_address or ("",))[0]
        return bool(self.headers.get("X-Forwarded-For")) or peer not in ("127.0.0.1", "::1")

    def _authed(self):
        if not self._is_remote():
            return True
        tok = _panel_token()
        if not tok:
            return False                      # токен не настроен — наружу закрыто наглухо
        return ("lb_panel=" + tok) in (self.headers.get("Cookie") or "")

    def _gate(self, path):
        """True — запрос обработан (вход по токену или отказ); False — пускать дальше."""
        # СОПРЯЖЕНИЕ С LEADCHAT — вызов сервер-сервер, у него нет и не может быть куки
        # панели. Своя дверь со своим ключом (LEADBOT_SERVICE_TOKEN): панельный секрет
        # для чужого сервиса не годится — он открывает всю переписку и настройки.
        if path == LEADCHAT_PATH:
            if leadchat.token_ok(self.headers):
                return False
            self._send(401, {"error": "нужен служебный токен",
                             "hint": "Authorization: Bearer <LEADBOT_SERVICE_TOKEN>"})
            return True
        # ОЧЕРЕДЬ ЗАЯВОК ДЛЯ РАСШИРЕНИЯ — тоже сервер-сервер, свой ключ (crm.extension_token
        # в config.json): панельная кука для офисного браузера-робота не годится.
        if path.startswith("/api/crm/"):
            if _crm_ext_token_ok(self.headers):
                return False
            self._send(401, {"error": "нужен токен расширения",
                             "hint": "X-Crm-Token из config.json → crm.extension_token"})
            return True
        if path.startswith("/panel/"):        # вход по секретной ссылке
            tok = _panel_token()
            if tok and path == "/panel/" + tok:
                self.send_response(302)
                self.send_header("Set-Cookie",
                                 "lb_panel=%s; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000" % tok)
                self.send_header("Location", "/panel")
                self.end_headers()
                return True
            self._send(403, {"error": "неверная ссылка"})
            return True
        if not self._authed():
            self._send(403, {"error": "нет доступа: откройте панель по секретной ссылке"})
            return True
        return False

    def log_message(self, fmt, *args):
        try:
            print("[%s] %s" % (_now(), fmt % args))
        except Exception:
            pass  # логирование не должно ронять обработчик (напр. закрытый stdout)

    def handle_error(self, request, client_address):
        """Клиент закрыл вкладку на середине ответа — это не ошибка сервера.
        ⚠ 12.08: в журнале за неделю лежал полный traceback BrokenPipeError от панели,
        и он мешал искать настоящие исключения. Молчим только про разрыв связи."""
        import sys as _sys
        if isinstance(_sys.exc_info()[1], (BrokenPipeError, ConnectionResetError)):
            return
        super().handle_error(request, client_address)

    def _send(self, code, obj=None, ctype="application/json"):
        self.send_response(code)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        # ⚠ CORS-заголовков нет НАРОЧНО (аудит 15.08). Раньше стояло
        # Access-Control-Allow-Origin: * — приглашение любому чужому сайту читать
        # ответы наших ручек из браузера оператора; выручала только SameSite-кука.
        # Двух заборов лучше, чем один: легитимным клиентам разрешение не нужно —
        # панель и оператор тот же origin, мост LeadChat и curl CORS не проверяют.
        self.end_headers()
        if obj is None:
            return
        if isinstance(obj, (dict, list)):
            self.wfile.write(json.dumps(obj, ensure_ascii=False).encode("utf-8"))
        else:
            self.wfile.write(obj if isinstance(obj, bytes) else str(obj).encode("utf-8"))

    def _body(self):
        n = int(self.headers.get("Content-Length", 0) or 0)
        if not n:
            return {}
        raw = self.rfile.read(n).decode("utf-8", "replace")   # кривую кодировку не роняем
        try:
            return json.loads(raw)
        except ValueError:
            return {}

    def do_OPTIONS(self):
        self._send(204)

    def do_GET(self):
        path = urlparse(self.path).path
        if self._gate(path):
            return
        if path in ("/", "/index.html"):
            return self._serve_file("test-client.html", "text/html")
        if path == "/operator":
            return self._serve_file("operator.html", "text/html")
        if path == "/relay":
            return self._serve_file("relay.html", "text/html")
        if path == "/review":
            return self._serve_file("review.html", "text/html")
        if path == "/panel":
            return self._serve_file("panel.html", "text/html")
        # ── ДОКУМЕНТЫ И ЛОГИ (02.08, просьба заказчика «с любого устройства») ──
        # закрыто тем же токен-гардом, что и всё остальное (_gate выше). Только чтение,
        # только белый список расширений, без обхода путей.
        if path == "/docs" or path == "/docs/":
            items = []
            try:
                for fn in sorted(os.listdir(os.path.join(ROOT, "analysis"))):
                    if fn.lower().endswith((".md", ".txt", ".html")) and not fn.startswith("_"):
                        items.append(fn)
            except OSError:
                pass
            rows = "".join(
                "<li><a href='/docs/%s'>%s</a></li>" % (urllib.request.quote(fn), fn)
                for fn in items)
            page = ("<!doctype html><html lang=ru><meta charset=utf-8>"
                    "<title>Лид-бот · документы</title>"
                    "<body style='font:15px/1.6 sans-serif;max-width:720px;margin:24px auto;padding:0 12px'>"
                    "<h2>Документы Лид-бота</h2>"
                    "<p><a href='/panel'>← в панель</a> · <a href='/docs/_log'>журнал сервера</a></p>"
                    "<ul>%s</ul></body></html>" % rows)
            return self._send(200, page.encode("utf-8"), "text/html")
        if path == "/docs/_log":
            # последние строки журнала службы (работает только на VPS под systemd)
            try:
                import subprocess
                out = subprocess.run(["journalctl", "-u", "leadbot", "-n", "300", "--no-pager"],
                                     capture_output=True, timeout=10).stdout
                return self._send(200, out or "журнал пуст".encode("utf-8"), "text/plain")
            except Exception as e:
                return self._send(200, ("журнал недоступен (не VPS?): %s" % e).encode("utf-8"),
                                  "text/plain")
        if path.startswith("/docs/"):
            raw = path[len("/docs/"):]
            # http.server декодирует строку запроса как latin-1 — кириллицу восстанавливаем
            try:
                raw = raw.encode("iso-8859-1").decode("utf-8")
            except (UnicodeDecodeError, UnicodeEncodeError):
                pass
            name = os.path.basename(urllib.request.unquote(raw))
            if not name.lower().endswith((".md", ".txt", ".html")):
                return self._send(404, {"error": "не найдено"})
            p = os.path.join(ROOT, "analysis", name)
            if not os.path.isfile(p):
                return self._send(404, {"error": "не найдено"})
            ctype = "text/html" if name.lower().endswith(".html") else "text/plain"
            with open(p, "rb") as f:
                return self._send(200, f.read(), ctype)
        if path == "/api/channel/overview":
            return self._send(200, channel.overview())
        if path == "/api/crm/queue":
            return self._send(200, {"pending": _crm_queue_pending()})
        if path == "/api/crm/money":
            # сводка по исходам: сколько заявок оплачено, сколько списано, сколько ждут
            return self._send(200, _crm_деньги())
        if path == "/api/crm/tracked":
            # созданные заявки без известного исхода — расширение читает их карточки
            return self._send(200, {"items": _crm_tracked()})
        if path == "/api/cities":
            # настройка городов (просьба заказчика 15.08): свод справочника,
            # пометок «-», закрытых филиалов и живых правок из city_overrides.json
            qs0 = parse_qs(urlparse(self.path).query)
            return self._send(200, _cities_overview((qs0.get("dir") or ["kp"])[0]))
        if path == "/api/channel/chat":
            key = (parse_qs(urlparse(self.path).query).get("key") or [""])[0]
            d = channel.chat_detail(key)
            return self._send(200, d if d else {"error": "чат не найден (ещё не опрошен?)"})
        if path == "/api/channel/stats":
            qs = parse_qs(urlparse(self.path).query)
            days = (qs.get("days") or ["14"])[0]
            try:
                return self._send(200, stats.overview(days=days,
                                                      channel_data=channel.overview()))
            except Exception as e:                 # статистика не должна ронять панель
                return self._send(200, {"error": "статистика недоступна: %s" % e})
        if path == "/api/review/data":
            # 100 сгенерированных диалогов + текущая разметка заказчика
            out = {"dialogs": [], "marks": {}}
            try:
                p = os.path.join(ROOT, "analysis", "review_dialogs.json")
                if os.path.exists(p):
                    out["dialogs"] = json.load(open(p, encoding="utf-8")).get("dialogs", [])
            except Exception as e:
                out["error"] = "диалоги: %s" % e
            try:
                p = os.path.join(ROOT, "analysis", "review_marks.json")
                if os.path.exists(p):
                    out["marks"] = json.load(open(p, encoding="utf-8"))
            except Exception:
                pass
            return self._send(200, out)
        if path == "/api/live":
            try:
                return self._send(200, {"dialogs": jivo_live.summaries()})
            except Exception as e:
                return self._send(200, {"dialogs": [], "error": str(e)})
        if path == "/api/live/dialog":
            q = parse_qs(urlparse(self.path).query)
            key = (q.get("key") or [""])[0]
            try:
                return self._send(200, jivo_live.get_dialog(key) or {})
            except Exception as e:
                return self._send(200, {"error": str(e)})
        if path == "/api/dialogs":
            with _LOCK:
                items = [{"id": d["id"], "title": d["title"], "updated": d["updated"],
                          "ready": d["ready"], "handoff": d["handoff"],
                          "category": d["state"]["category"]}
                         for d in _DIALOGS.values()]
            return self._send(200, {"dialogs": items})
        if path == "/api/dialog":
            q = parse_qs(urlparse(self.path).query)
            did = (q.get("id") or [""])[0]
            with _LOCK:
                d = _DIALOGS.get(did)
                return self._send(200, d or {})
        if path == "/api/health":
            c = claude_api.config()
            return self._send(200, {"ok": True, "model_hard": c.get("model_hard"),
                                    "model_simple": c.get("model_simple"),
                                    "tiering": c.get("tiering"), "cache": c.get("use_cache")})
        return self._send(404, {"error": "not found"})

    def do_POST(self):
        path = urlparse(self.path).path
        if self._gate(path):
            return
        if path == LEADCHAT_PATH:
            try:
                body = self._body()
            except Exception:
                body = None
            out, code = leadchat_answer(body if isinstance(body, dict) else {})
            return self._send(code, out)
        if path == "/api/message":
            body = self._body()
            msgs = body.get("messages")
            if isinstance(msgs, list):
                # Пульт: клиент прислал всю историю — стейтлесс, контекст не теряется
                try:
                    _t0 = time.time()
                    r = run_relay(msgs, known=body.get("known"))
                    logbook.relayed(
                        r,
                        source="panel",
                        ms=int((time.time() - _t0) * 1000),
                        dialog_len=len(msgs),
                    )
                    return self._send(400 if r.get("error") else 200, r)
                except claude_api.ClaudeError as e:
                    return self._send(502, {"error": str(e)})
            did = (body.get("dialog_id") or "").strip() or None
            text = (body.get("text") or "").strip()
            if not text:
                return self._send(400, {"error": "пустой текст"})
            if did is None:
                with _LOCK:
                    d = _new_dialog(title=body.get("title"))
                    did = d["id"]
            try:
                return self._send(200, run_turn(did, text, known=body.get("known")))
            except claude_api.ClaudeError as e:
                return self._send(502, {"error": str(e)})
        if path == "/api/channel/accounts":
            body = self._body()
            try:
                if body.get("patch"):
                    acc = next((a for a in channel.accounts() if a.get("id") == body.get("id")), None)
                    if not acc:
                        return self._send(404, {"error": "аккаунт не найден"})
                    for k in ("enabled", "auto_reply", "label", "direction", "city",
                              "partner", "persona"):
                        if k in body:
                            acc[k] = body[k]
                    channel.save_account(acc)
                    return self._send(200, {"ok": True})
                acc = channel.save_account(body)
                ok, detail = avito_api.check(acc)
                return self._send(200, {"ok": True, "id": acc["id"],
                                        "check_ok": ok, "check_detail": detail})
            except (ValueError, avito_api.AvitoError) as e:
                return self._send(400, {"error": str(e)})
        if path == "/api/channel/accounts/delete":
            channel.delete_account((self._body() or {}).get("id"))
            return self._send(200, {"ok": True})
        if path == "/api/channel/accounts/test":
            body = self._body()
            acc = next((a for a in channel.accounts() if a.get("id") == body.get("id")), None)
            if not acc:
                return self._send(404, {"error": "аккаунт не найден"})
            ok, detail = avito_api.check(acc)
            return self._send(200, {"ok": ok, "detail": detail})
        if path == "/api/channel/send":
            body = self._body()
            text = (body.get("text") or "").strip()
            if not text:
                return self._send(400, {"error": "пустой текст"})
            try:
                channel.send_reply(body.get("key") or "", text)
                return self._send(200, {"ok": True})
            except (ValueError, avito_api.AvitoError) as e:
                return self._send(400, {"error": str(e)})
        if path == "/api/channel/refresh":
            try:
                d = channel.refresh_draft((self._body() or {}).get("key") or "")
                return self._send(200, d if d else {"error": "чат не найден"})
            except claude_api.ClaudeError as e:
                return self._send(502, {"error": str(e)})
        if path == "/api/channel/registry":
            body = self._body()
            if not body.get("item_id"):
                return self._send(400, {"error": "нет item_id"})
            out = channel.save_registry_item(body["item_id"], body.get("fields") or {})
            return self._send(200, {"ok": True, "item": out})
        if path == "/api/crm/claim":
            body = self._body()
            key = (body.get("key") or "").strip()
            if not key:
                return self._send(400, {"error": "нет key"})
            взят = _crm_queue_claim(key)
            if not взят:
                print("[ЗАЯВКА] захват %s отклонён (уже в работе или закрыт)" % key,
                      flush=True)
            return self._send(200, {"ok": взят})
        if path == "/api/crm/drop":
            # СНЯТЬ ЛИД ИЗ ОЧЕРЕДИ РУКАМИ (просьба владельца 25.08): дубль, ошибка бота,
            # клиент передумал. Заявка в CRM при этом НЕ создаётся и не удаляется —
            # ручка трогает только нашу очередь.
            body = self._body()
            key = (body.get("key") or "").strip()
            if not key:
                return self._send(400, {"error": "нет key"})
            прежний = _crm_queue_all().get(key) or {}
            if not прежний:
                return self._send(404, {"error": "лида нет в очереди"})
            if прежний.get("status") in _CRM_ЗАКРЫТЫЕ:
                # уже закрыт — повтор снятия не ошибка и вторую запись не пишет
                return self._send(200, {"ok": True, "status": прежний.get("status")})
            _crm_queue_mark(key, "dropped",
                            {"by": "human", "reason": (body.get("reason") or "")[:200]})
            print("[ЗАЯВКА] снята из очереди руками: %s%s"
                  % (key, (" — " + body["reason"][:100]) if body.get("reason") else ""),
                  flush=True)
            return self._send(200, {"ok": True, "status": "dropped"})
        if path == "/api/crm/status":
            # ⚠ ТОЛЬКО ЗАПИСЬ ИСХОДА, БЕЗ РЕШЕНИЙ. Что делать с «Отменой КЦ» — вопрос
            # разбора, когда статусов наберётся достаточно; на трёх заявках выводов нет.
            сохранено = _crm_status_save((body or {}).get("статусы"))
            if сохранено:
                _д = _crm_деньги()
                print("[ЗАЯВКА] статусы из CRM: обновлено %d | %+d ₽ "
                      "(оплачено %d, списано %d, ждут исхода %d)"
                      % (сохранено, _д["рублей"], _д["плюс"], _д["минус"], _д["ждём"]),
                      flush=True)
            return self._send(200, {"ok": True, "сохранено": сохранено})
        if path == "/api/crm/result":
            body = self._body()
            key = (body.get("key") or "").strip()
            if not key:
                return self._send(400, {"error": "нет key"})
            ok = bool(body.get("ok"))
            прежний = _crm_queue_all().get(key) or {}
            if прежний.get("status") in _CRM_ЗАКРЫТЫЕ:
                if прежний.get("status") == "dropped":
                    # лид сняли из попапа, пока расширение его создавало — это не дубль,
                    # а гонка человека с роботом; в CRM заявка всё же появилась
                    print("[ЗАЯВКА] отчёт по СНЯТОМУ лиду %s (№%s): проверьте карточку в CRM"
                          % (key, body.get("id") or "?"), flush=True)
                    return self._send(200, {"ok": True, "dropped": True})
                # повторный отчёт (второй опрос успел создать дубль) — журнал не
                # засоряем, но кричим: дубль надо убрать в CRM руками
                print("[ЗАЯВКА] ПОВТОРНЫЙ отчёт по %s (№%s) — возможен ДУБЛЬ в CRM!"
                      % (key, body.get("id") or "?"), flush=True)
                return self._send(200, {"ok": True, "dup": True})
            # ⚠ ПРЕДУПРЕЖДЕНИЯ РАСШИРЕНИЯ ДОХОДЯТ ДО ЖУРНАЛА (26.08). Раньше «вид работ
            # не подобран» видел только владелец в попапе, и понять, часто ли это, было
            # нечем. Теперь это в журнале бота рядом с самой заявкой.
            предупр = [str(x)[:200] for x in (body.get("warnings") or [])][:6]
            if предупр:
                print("[ЗАЯВКА] предупреждения расширения (%s): %s"
                      % (key, "; ".join(предупр)), flush=True)
            _spravochnik_save(body.get("spravochnik"))
            extra = {"id": body.get("id"), "errors": (body.get("errors") or [])[:5],
                     "warnings": предупр, "by": "extension",
                     # версия расширения: поведение между версиями разное, и без неё
                     # разбор «почему поле пустое» упирается в догадки о том, что стоит
                     # на офисном ПК
                     "ext": str(body.get("ext") or "")[:16],
                     # что выбрано в ЭТОЙ заявке: справочник пишется только при
                     # изменении списка, и проверять подбор по нему нельзя
                     "vid": _вид_работ_кратко(body.get("vid_rabot"))}
            _crm_queue_mark(key, "done" if ok else "failed", extra)
            if ok:
                print("[ЗАЯВКА] создана расширением: №%s (%s)"
                      % (body.get("id") or "?", key), flush=True)
            else:
                print("[ЗАЯВКА] расширение не смогло (%s): %s"
                      % (key, "; ".join(extra["errors"]) or "без деталей"), flush=True)
            return self._send(200, {"ok": True})
        if path == "/api/cities":
            body = self._body()
            err = _cities_save(body)
            if err:
                return self._send(400, {"error": err})
            return self._send(200, {"ok": True,
                                    "cities": _cities_overview(body.get("dir") or "kp")})
        if path == "/api/review/save":
            # разметка страницы оценки: пишем целиком, атомарно (tmp -> replace)
            body = self._body()
            marks = body.get("marks")
            if not isinstance(marks, dict):
                return self._send(400, {"error": "нет marks"})
            p = os.path.join(ROOT, "analysis", "review_marks.json")
            tmp = p + ".tmp"
            try:
                with _LOCK:
                    with open(tmp, "w", encoding="utf-8") as f:
                        json.dump(marks, f, ensure_ascii=False, indent=1)
                    os.replace(tmp, p)
                return self._send(200, {"ok": True, "saved": len(marks)})
            except Exception as e:
                return self._send(500, {"error": str(e)})
        if path == "/api/reset":
            body = self._body()
            did = (body.get("dialog_id") or "").strip()
            with _LOCK:
                _DIALOGS.pop(did, None)
            return self._send(200, {"ok": True})
        if path == "/api/suggest":
            body = self._body()
            d = jivo_live.get_dialog((body.get("key") or "").strip())
            if not d:
                return self._send(404, {"error": "диалог не найден"})
            fl = d.get("flag")
            if fl and not body.get("force"):
                # слив/отказ — отдаём шаблон локально, БЕЗ обращения к шлюзу (0 токенов)
                return self._send(200, {
                    "reply": fl["draft"], "deflect": True,
                    "flag": {"kind": fl["kind"], "sub": fl.get("sub"), "reason": fl["reason"]},
                    "cached": True, "model": "локальный фильтр",
                    "state": {}, "ready": False, "handoff": fl["kind"] != "refuse",
                })
            try:
                _t0 = time.time()
                _res = suggest_reply(d.get("messages") or [], known=d)
                shadow.ход(d.get("messages") or [], d, _res,
                           ms=int((time.time() - _t0) * 1000),
                           стадия=getattr(_ХОД, "стадия", ""), источник="пульт")
                return self._send(200, _res)
            except claude_api.ClaudeError as e:
                return self._send(502, {"error": str(e)})
        if path == "/api/compare":
            body = self._body()
            d = jivo_live.get_dialog((body.get("key") or "").strip())
            if not d:
                return self._send(404, {"error": "диалог не найден"})
            try:
                return self._send(200, {"pairs": compare_dialog(d.get("messages") or [], known=d)})
            except claude_api.ClaudeError as e:
                return self._send(502, {"error": str(e)})
        return self._send(404, {"error": "not found"})

    def _serve_file(self, name, ctype):
        p = os.path.join(UI_DIR, name)
        if not os.path.exists(p):
            return self._send(404, {"error": name + " не найден"})
        with open(p, "rb") as f:
            data = f.read()
        return self._send(200, data, ctype)


def main():
    cfg = claude_api.config()
    _load_answer_cache()
    print("Кэш ответов: загружено %d записей" % len(_ANSWER_CACHE))
    host = os.environ.get("LEADBOT_HOST") or cfg.get("host", "127.0.0.1")
    port = int(os.environ.get("LEADBOT_PORT") or cfg.get("port", 8788))
    srv = ThreadingHTTPServer((host, port), Handler)
    # свой канал Avito: фоновый опросчик аккаунтов из панели (черновики; автоответ — по тумблеру)
    channel.start(run_relay, debounce_fn=debounce_wait)
    print("Лид-бот запущен на http://%s:%d" % (host, port))
    print("  ПАНЕЛЬ БОТА:     http://%s:%d/panel      (свой канал Avito: аккаунты, чаты, реестр)" % (host, port))
    print("  Окно оператора:  http://%s:%d/operator   (живые чаты Jivo + черновик ответа)" % (host, port))
    print("  Тестовый чат:    http://%s:%d/" % (host, port))
    print("  Модели: %s (сложные) / %s (рутина), tiering=%s, cache=%s" % (
        cfg.get("model_hard"), cfg.get("model_simple"), cfg.get("tiering"), cfg.get("use_cache")))
    print("Ctrl+C — остановить.")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nОстановлено.")


if __name__ == "__main__":
    main()
